  Stage_122178_Name = {
    Text = "Gözleri Örtmek·Çılgınlık"
  },
  Stage_122179_Desc = {
    Text = "İdeali, ışığı ve umudu sonsuza dek kovalamak—bedenimin kurban edilmesi pahasına bile olsa. Ey Tanrım, yalnızca şunu diliyorum: Böylesine korkusuzca yürüdüğüm yol, senin takdir ettiğin yol olsun."
  },
  Stage_122179_Name = {
