  Stage_122601_Name = {
    Text = "Mouchette Sınavı"
  },
  Stage_123112_Desc = {
    Text = "Sisler gözlerimi perdeledi, beni kendi dünyama bağlayan bağı kopardı. Yine de, senin gözlerinden, asla dönemeyeceğim geçmişi ve bir daha asla kavuşamayacağım insanları görüyorum. Biz Hısım’ız."
  },
  Stage_123112_Name = {
    Text = "Senin Bakışınla"
  },
  Stage_123113_Desc = {
    Text = "Sisler gözlerimi perdeledi, beni kendi dünyama bağlayan bağı kopardı. Yine de, senin gözlerinden, asla dönemeyeceğim geçmişi ve bir daha asla kavuşamayacağım insanları görüyorum. Biz Hısım’ız."
  },
  Stage_123113_Name = {
    Text = "Senin Bakışınla"
  },
  Stage_125199_Desc = {
    Text = "Yalnızca aşka müptela böcek böylesine kırılgan, böylesine inatçı, böylesine gülünç ve yine de böylesine olağanüstüdür.\nAh, benimle gel de daha da harikulade bir şey gör. Birbirinize göz kulak olacaksınız ve artık ayrılmazcasına birbirinize bağlanacaksınız."
  },
  Stage_125199_Name = {
    Text = "İpek Tuzak·Üçüncü"
  },
  Stage_125200_Desc = {
    Text = "Tutkulu aşk mutlaka sonunu bulur; ama son, her zaman birlikte ihtiyarlamak değildir; çoğu zaman, zamansız bir ölümdür.\nBazen boşuna ölen aşktır, bazense sensin."
  },
  Stage_125200_Name = {
    Text = "Haksız Ölüm·Çılgınlık"
  },
  Stage_125201_Desc = {
    Text = "Eski âşığın çoktan ölü ruhlar arasına karıştı; pişmanlığı neden ancak şimdi hissetmeye başlıyorsun?\nHihi… tasalanma; henüz çok geç değil. Bak, sevgilim. Güneş battığı sürece, her lamba, her kırmızı mum, her kâğıt pencereye onun suretini ve gölgesini düşürecek."
  },
  Stage_125201_Name = {
    Text = "Arkadaki Gölge:·II"
  },
  Stage_125202_Desc = {
    Text = "\"...Bir ağustosböceğinin kabuğunu soyup kemiklerini yenilemesi gibi, buna “Ceset Yükselişi” denir—bedensel Çözünme yoluyla ölümsüzlüğe yükselmek...\"\nAma aslında—hiç de doğru değildir. Bu sadece gülünç, eski bir masal. Peki ne fark eder? Onlar kan ve gözyaşlarıyla dua ettiler ve bu dualardan, bir güzellik—ya da katıksız bir dehşet—yeniden doğdu."
  },
  Stage_125202_Name = {
    Text = "Ceset Yükselişi:·Altıncı"
  },
  Stage_125203_Desc = {
    Text = "Eski âşığın çoktan ölü ruhlar arasına karıştı; pişmanlığı neden ancak şimdi hissetmeye başlıyorsun?\nHihi… tasalanma; henüz çok geç değil. Bak, sevgilim. Güneş battığı sürece, her lamba, her kırmızı mum, her kâğıt pencereye onun suretini ve gölgesini düşürecek."
  },
  Stage_125203_Name = {
    Text = "Arkadaki Gölge:·Birinci"
  },
  Stage_125204_Desc = {
    Text = "Adak masasının önünde birlikte diz çökerler. Obsidyen Anaerkil, fark edilmez, tarif edilmez ve karşı konulmazdır.\nHer şeyi sun, her buyruğa uy; en yüce vecde, ebedî kaosa yüksel."
  },
  Stage_125204_Name = {
    Text = "Coşku·Çılgınlık"
  },
  Stage_125205_Desc = {
    Text = "Kokunu seviyorum; düşmanlarının tadına senin yerine ben bakacağım."
  },
  Stage_125205_Name = {
    Text = "Kokunun İzinde:·II"
  },
  Stage_125206_Desc = {
    Text = "O esrarengiz tarikat, kadim doğu ulusunun tarih kayıtlarının dışında sürüklenir; ne keşfedilebilir ne de tanımlanabilir. Yalnızca çok az sayıda kişi, hâlâ yok olmamış ve sonsuza dek Rüyasız Diyar’da ikamet eden o seçilmişler, onun taptığı ilahın gerçek adını öğrenebilmiştir.\nOnun adı—\"@4\""
  },
  Stage_125206_Name = {
    Text = "Kabaran Lütuf·Birinci"
  },
  Stage_125207_Desc = {
    Text = "Adak masasının önünde birlikte diz çökerler. Obsidyen Anaerkil, fark edilmez, tarif edilmez ve karşı konulmazdır.\nHer şeyi sun, her buyruğa uy; en yüce vecde, ebedî kaosa yüksel."
  },
  Stage_125207_Name = {
    Text = "Coşku·Altıncı"
  },
  Stage_125208_Desc = {
    Text = "Çıt—şapır—gurgur—mmph—\nSonsuza dek birlikte olacağız, sonsuza dek birlikte olacağız.\nSonsuza dek birlikte olacaĞIzeBİRLİKTEsonsuzAdek-ebedİYE@4"
  },
  Stage_125208_Name = {
    Text = "Emme·Birinci"
  },
  Stage_125209_Desc = {
    Text = "Çıt—şapır—gurgur—mmph—\nSonsuza dek birlikte olacağız, sonsuza dek birlikte olacağız.\nSonsuza dek birlikte olacaĞIzeBİRLİKTEsonsuzAdek-ebedİYE@4"
  },
