  Stage_125214_Desc = {
    Text = "Şşşt—şlak.\nGerçekten de, bu dünyada bundan daha basit—ya da daha zor—pek az şey vardır."
  },
  Stage_125214_Name = {
    Text = "Ata’nın Kanı"
