  Stage_125216_Desc = {
    Text = "Tutkulu aşk mutlaka sonunu bulur; ama son, her zaman birlikte ihtiyarlamak değildir; çoğu zaman, zamansız bir ölümdür.\nBazen boşuna ölen aşktır, bazense sensin."
  },
  Stage_125216_Name = {
    Text = "Haksız Ölüm:·Beşinci"
  },
  Stage_125217_Desc = {
    Text = "Şakak şakağa, kollar sarmalamış, boyun boyuna.\nSevgilim, en sevgilim—kalbimin ta kendisi olmasaydın, sana nasıl “en sevgilim” diyebilirdim?"
  },
  Stage_125217_Name = {
    Text = "Ah, Benim En Sevgilim"
