  Stage_125649_Desc = {
    Text = "Okyanusun ötesindeki kasırga hiçbir zaman kelebeğin tercihine bağlı olmadı."
  },
  Stage_125649_Name = {
    Text = "Silah sesleri"
  },
  Stage_125650_Desc = {
    Text = "Aslında, uzaktaki tanrılar hiçbir zaman uyanmayı arzulamamıştır."
  },
  Stage_125650_Name = {
    Text = "İlahi Yansıma"
  },
  Stage_125651_Desc = {
    Text = "Bu, dikenlerden ve alevlerden daha acı verici bir cezadır."
  },
  Stage_125651_Name = {
    Text = "Şefkatli Zincirler"
  },
  Stage_125652_Desc = {
    Text = "En zarif hareketler her zaman ölüm ve yıkımın ortasında çiçek açar."
  },
  Stage_125652_Name = {
    Text = "Uç, Kuğu, Uç"
  },
  Stage_125653_Desc = {
    Text = "90 dakikalık gece yarısı, 15 inçlik bir maske, 10 galon rüya ve 2 ons alkol—hazzın tek tarifi."
  },
  Stage_125653_Name = {
    Text = "Maskeli Balo"
  },
  Stage_125654_Desc = {
    Text = "Titizlikle prova edilmiş yeni bir oyun—izlemesi bedava, ayrılması yasak."
  },
  Stage_125654_Name = {
    Text = "İçimizdeki Aktör"
  },
  Stage_125655_Desc = {
    Text = "Gül ve şarkı söyle! Dostum! Kaderin sahnesinde zevk tek başrol oyuncusudur."
  },
  Stage_125655_Name = {
    Text = "Doğaçlama Komedi"
  },
  Stage_125656_Desc = {
    Text = "Rollerimiz tiyatroya girmeden önce çoktan belirlenmiştir."
  },
  Stage_125656_Name = {
    Text = "Seyirci, Oyuncu, Yazar"
  },
  Stage_125657_Desc = {
    Text = "Bu, dikenlerden ve alevlerden daha acı verici bir cezadır."
  },
  Stage_125657_Name = {
