  Stage_125660_Desc = {
    Text = "Cadrin Malikanesi, ihtişam ve çöküş dramlarından zevk alır. Yalnızca malikaneyi memnun etmeyi öğrenenler davetiye alır."
  },
  Stage_125660_Name = {
    Text = "Malikanenin Davetiyesi"
  },
  Stage_125661_Desc = {
    Text = "Oyuncular sahneye çıkar; yazar bilinmez kalır."
  },
  Stage_125661_Name = {
    Text = "İkinci Perde"
  },
  Stage_125662_Desc = {
    Text = "Okyanusun ötesindeki kasırga hiçbir zaman kelebeğin tercihine bağlı olmadı."
  },
  Stage_125662_Name = {
    Text = "Silah sesleri"
  },
  Stage_125663_Desc = {
    Text = "Ölümsüz kafes, tutsakların kendi elleriyle örülmüştür.\nSonsuza dek örerler. Hiç kaçamamışlardır."
  },
  Stage_125663_Name = {Text = "Koza"},
  Stage_126202_Desc = {
    Text = "Çiçekler, tezahüratlar, alkışlar. Dünya bir kez daha onun üzerinde birleşir.\nAnlatının büyücüsü gösteriyi bitirmiştir; seyircilerin anıları zarif bir reverans arasında erir.\nHiçbir sır, ne kadar karanlık olursa olsun, sahnenin harabelerinden asla kaçamaz."
  },
  Stage_126202_Name = {
    Text = "Spoiler Yok: IV"
  },
  Stage_126203_Desc = {
    Text = "İşte—hikâyenin doruk noktası! Her ipucu yalnızca yakıttır; her hazırlık, bu taçlandırma anında sahneyi tutuşturacak bir kıvılcım."
  },
  Stage_126203_Name = {
    Text = "Yanış: IV"
  },
  Stage_126204_Desc = {
    Text = "Bir kukla için can sıkıntısı tek ölüm günahıdır."
  },
  Stage_126204_Name = {
    Text = "Sürpriz Dönüşler: IV"
  },
  Stage_126208_Desc = {
    Text = "Perde açılır, ama ne seyirci ne de alkışları kalmıştır.\nDünya boş uzanır, yalnızca tek bir ışık biricik sahneyi aydınlatır."
  },
  Stage_126208_Name = {Text = "Giriş: VI"},
