  Stage_129163_Name = {
    Text = "Telaşlı Gökyüzü Hattı: Normal"
  },
  Stage_129164_Name = {
    Text = "Telaşlı Gökyüzü Hattı: Zor"
  },
  Stage_129165_Name = {
    Text = "Telaşlı Gökyüzü Hattı: ·Çılgınlık"
  },
  Stage_129500_Desc = {
    Text = "Panlong İmparatorluğu’nda her Bahar Festivali’nde, ülkenin dört bir yanından aileler kavuşmak için bir araya gelir.\nBahar Festivali yaklaşırken, uzak diyarlara giden trenlere binerler; rüyalarına tutunur, uzun zamandır beklenen kavuşma anını sabırsızlıkla beklerler."
  },
  Stage_129500_Name = {
    Text = "Eve Dönüş Treni"
  },
  Stage_129501_Desc = {
    Text = "Korkma; bu yalnızca bir oyun.\nMutlak, soğukkanlı bir gaddarlığın oyunu."
  },
  Stage_129501_Name = {
    Text = "Oyun Başlasın"
  },
  Stage_129502_Desc = {
    Text = "Durma. Geri çekilme.\nÇünkü iyiler silahlarını indirirse, yeryüzünü kötüler miras alır."
  },
  Stage_129502_Name = {
    Text = "İkinci Kurban"
  },
  Stage_129503_Desc = {
    Text = "Adil bir karşı saldırı... yoksa değil mi?"
  },
  Stage_129503_Name = {
    Text = "Sessiz Öldürme"
  },
  Stage_129504_Desc = {
    Text = "O kol, rüyalarının kıyılarında dolaşır.\nİleri itmek mi, geri çekmek mi... işte bütün soru."
  },
  Stage_129504_Name = {
    Text = "Işıksız Kabin"
  },
  Stage_129505_Desc = {
    Text = "Havai fişekler göğü tutuşturur, eski yılı yakıp kül eder; geçmiş, geri alınma umudunun ötesinde küle döner."
  },
  Stage_129505_Name = {
    Text = "Dünün Parıltıları"
  },
  Stage_130109_Desc = {
    Text = "İnsanlar okula gitmek zorunda ve Uyandırıcılar da okula gitmek zorunda.\nArtık bir Uyandırıcı olduğuna göre, doğal olarak onun da okula gitmesi gerekiyor.\nLütfen güvende kalmaya dikkat edin."
  },
  Stage_130109_Name = {Text = "Okulda: II"},
  Stage_130110_Desc = {
    Text = "Bir insan nasıl efsanevi bir dedektif olur? Birincisi, her derin kuyu pek çok sır barındırır.\nİkincisi, kendini dibine atmadan önce—unutma ki bir av tüfeğinin yasal olarak kayıtlı olması şart değildir."
  },
  Stage_130110_Name = {Text = "Kuyu: VI"},
  Stage_130111_Desc = {
    Text = "Bir insan nasıl efsanevi bir dedektif olur? Birincisi, her derin kuyu pek çok sır barındırır.\nİkincisi, kendini dibine atmadan önce—unutma ki bir av tüfeğinin yasal olarak kayıtlı olması şart değildir."
  },
  Stage_130111_Name = {Text = "Kuyu: II"},
  Stage_130112_Desc = {
    Text = "Evet, efsanevi bir Müfettiş bile her zaman kazanamayabilir.\n…Ama sorun değil, votkadan son bir damla kaldı."
  },
  Stage_130112_Name = {
    Text = "Gece Şapkası: IV"
  },
  Stage_130113_Desc = {
    Text = "Birbirini seven insanlar akşam yemeğinde bir araya gelir, kalplerindeki sırları birbirine döker.\nYiyecekler pek çok sır duymuştur; ancak doğal olarak, onlar hiçbir zaman konuşmazlar."
  },
  Stage_130113_Name = {
    Text = "Yemek Masası: IV"
  },
  Stage_130114_Desc = {
    Text = "İnsanlar okula gitmek zorunda ve Uyandırıcılar da okula gitmek zorunda.\nArtık bir Uyandırıcı olduğuna göre, doğal olarak onun da okula gitmesi gerekiyor.\nLütfen güvende kalmaya dikkat edin."
  },
  Stage_130114_Name = {
    Text = "Okulda: Delilik"
  },
  Stage_130115_Desc = {
    Text = "İnsanlar okula gitmek zorunda ve Uyandırıcılar da okula gitmek zorunda.\nArtık bir Uyandırıcı olduğuna göre, doğal olarak onun da okula gitmesi gerekiyor.\nLütfen güvende kalmaya dikkat edin."
  },
  Stage_130115_Name = {
    Text = "Okulda: III"
  },
  Stage_130116_Desc = {
    Text = "Tavanı sevdiğin renge boya, duvarları sevdiğin renge boya.\nBuzdolabını sevdiğin yiyeceklerle doldur, ikimizin de sevdiği bir evcil hayvan besle.\nBurası yalnızca sana ve bana ait Evimiz."
  },
  Stage_130116_Name = {Text = "Evimiz: VI"},
  Stage_130117_Desc = {
    Text = "Birbirini seven insanlar akşam yemeğinde bir araya gelir, kalplerindeki sırları birbirine döker.\nYiyecekler pek çok sır duymuştur; ancak doğal olarak, onlar hiçbir zaman konuşmazlar."
  },
  Stage_130117_Name = {
    Text = "Yemek Masası: III"
  },
  Stage_130118_Desc = {
    Text = "Hastane inanılmaz bir yerdir; aynı anda yeniden doğuşu, ölümü, dirilişi, dünyanın en büyük acısını ve dünyanın en büyük sevincini bir arada barındırır.\nAncak insanların sevinçleri, üzüntüleri ve tüm duyguları birbirleriyle hiçbir şekilde buluşamaz."
  },
  Stage_130118_Name = {
    Text = "Hastane: II"
  },
  Stage_130119_Desc = {
    Text = "Evet, efsanevi bir Müfettiş bile her zaman kazanamayabilir.\n…Ama sorun değil, votkadan son bir damla kaldı."
  },
  Stage_130119_Name = {
    Text = "Gece Şapkası: Delilik"
  },
  Stage_130120_Desc = {
