    Text = "Güneş ışığı pencereden süzülüp meşe kokulu masaya dökülüyor.\nKitaplar bir kenara saçılmış, Vortice masanın üzerine tembelce yayılmış.\n\"Nautila Zzz... Coalsie Zzz... Ne kadar mutluyum~\"\nUzun süren soğuk ve yalnızlık sona erdi.\nİleride uzanan, çok ama çok daha iyi bir yarın."
  },
  Stage_130819_Name = {
    Text = "Güzel. En iyi. En iyisi!"
  },
  Stage_130820_Desc = {
    Text = "Balık yakala, ye, meyve ye, pırıl pırıl kabuklar bul, sakla, uyu!"
  },
  Stage_130820_Name = {
    Text = "Sıradan Günler·IV"
  },
  Stage_130821_Desc = {
    Text = "Her şey, biter, Vortice kaybeder, Vortice kazanır! Vortice, gidiyor... eve."
  },
  Stage_130821_Name = {
    Text = "Uzun Yolculuk Yurt:·Bölüm II"
  },
  Stage_130823_Desc = {
    Text = "Her şey, biter, Vortice kaybeder, Vortice kazanır! Vortice, gidiyor... eve."
  },
  Stage_130823_Name = {
    Text = "Uzun Yolculuk Yurt: Bölüm V"
  },
  Stage_130824_Desc = {
    Text = "Şıp.\nYağmur gemiye düşüyor, ne kadar da gürültülü.\nVortice, bundan nefret ediyor.\nŞıp. Şıp."
  },
  Stage_130824_Name = {
    Text = "Şıpır şıpır."
  },
  Stage_130825_Desc = {
    Text = "Şapır~ Şapır~\n\"Cik! (Al bakalım, Koca Olan!)\"\n\"Hımpf, Coalsie, yavaş!\"\nŞapır~ Şapır~\n\"Vortice! Bekle, bekle, çok soğuk.\"\n\"Dost, gel oyna!\"\n"
  },
  Stage_130825_Name = {
    Text = "Şıpır~ Şapır~"
  },
  Stage_130826_Desc = {
    Text = "Vortice, ileri! Dostlar, ileri! Coalsie, ileri!!"
  },
  Stage_130826_Name = {
