  },
  Stage_130834_Name = {
    Text = "Yelken Zamanı·Çılgınlık"
  },
  Stage_130835_Desc = {
    Text = "Fırtına geldi, Vortice korkmaz! Gök gürültüsü çok yüksek, Vortice korkmaz! Dost dedi, bu gece, zaferden, önceki gece!"
  },
  Stage_130835_Name = {
    Text = "Gürleyen Fırtına·Üçüncü"
  },
  Stage_130836_Desc = {
    Text = "Dost, dost! Hehe, yeni dost! Al, et!"
  },
  Stage_130836_Name = {
    Text = "Yeni Yoldaşlar·Bölüm V"
  },
  Stage_130837_Desc = {
