  },
  Stage_130839_Desc = {
    Text = "Karanlık. Yumuşak. Bayıldım!"
  },
  Stage_130839_Name = {
    Text = "Sürüklenen Gizli Hazineler·Beşinci"
  },
  Stage_130840_Desc = {
