  Stage_141235_Desc = {
    Text = "Sen oyun oynamayı seversin, her şeyi bir saçmalık olarak görürsün. Bu yüzden o İnananların boğazlarını keseceğiz, omurgalarını çiğneyeceğiz, ne kadar aptalca ve gülünç kirli bir şeye inandıklarını anlayacaklar.\nKaçmaya devam et, yoksa Yok Oluş'un bile yalnızca güzel bir Yanılsama olduğunu Keşfedeceksin."
  },
  Stage_141235_Name = {
    Text = "Yırtıcının Oyunu: I"
  },
  Stage_141236_Desc = {
    Text = "Kolay elde edilebilen, lezzetli, sağlam, sıkı, boğucu.\nKırılgan.\nO, tam burada var."
  },
  Stage_141236_Name = {
    Text = "Kaburga ve Kıkırdak: VI"
  },
  Stage_141237_Desc = {
    Text = "Evet, elbette biliyorum.\nBaşından beri, yalnızca \"Ben\" vardı, \"Biz\" yoktu."
  },
  Stage_141237_Name = {
    Text = "İç Konuşma: Delilik"
  },
  Stage_141238_Desc = {
    Text = "Avcı ile avın rolleri çoğu zaman bir anda yer değiştirir; binlerce yıl boyunca Döngü tekrarlanır, ta ki bir taraf araç kullanmayı öğrenene, ta ki bir taraf gerçek Gücü elde edene dek."
  },
  Stage_141238_Name = {
    Text = "Karanlık Orman: V"
  },
  Stage_141239_Desc = {
    Text = "Derin Deniz'den daha kadim bir varlık tarafından seçildi; geri dönemeyeceği o yerde kaldı."
  },
  Stage_141239_Name = {Text = "Islık: VI"},
  Stage_141240_Desc = {
    Text = "En şenlikli yiyecek, kutlamaya en uygun yiyecek; kadeh kaldırıyoruz, bir araya geliyoruz.\nKimse, bir bedenden diğerine aynı iradenin geçip geçmediğini umursamıyor; kimse, boş kabukların içinde hâlâ bir ruh olup olmadığını umursamıyor."
  },
  Stage_141240_Name = {
    Text = "Bal Şarabı ve Mür: IV"
  },
  Stage_141241_Desc = {
