  Stage_141275_Name = {
    Text = "İkicilik: Delilik"
  },
  Stage_141276_Desc = {
    Text = "Zaman pek çok şeyi siler, bazen kısa bir yas tutarlar, sonra her zamanki gibi devam eder.\nAma çok nadir durumlarda — şansın yaver gitmediği zamanlarda.\nHer yola başvurmaktan çekinmeyen bir Paranoya Pençesi ile karşılaşırsın."
  },
