  Stage_146229_Desc = {
    Text = "Sofraya oturanların hepsi geldi; uykudaki Tanrı sonunda güldü.\nSiz hiçbir zaman ziyafete gelen Misafir değildiniz."
  },
  Stage_146229_Name = {
    Text = "Ziyafetteki Konuklar"
  },
  Stage_146230_Desc = {
    Text = "Kar dağının tek bir kuralı vardır: Ne duyarsan duy, Cevap Verme."
  },
  Stage_146230_Name = {
    Text = "Cevap Verme"
  },
  Stage_146231_Desc = {
    Text = "Yedi Kurban, yedi kaide, dünyanın başlangıç noktasına açılan bir Kapı.\nDilekler hiçbir zaman bedava bir armağan değildi."
  },
  Stage_146231_Name = {
    Text = "Dileksiz Zirve"
  },
  Stage_146232_Desc = {
    Text = "Kuş sonunda diğer kuşu buldu.\nBugün uzaklara gidiyoruz, dönüş zamanını sormuyoruz."
  },
  Stage_146232_Name = {
    Text = "Bugün Kuşlar Göç Eder"
  },
  Stage_146233_Desc = {
    Text = "Berrak göl yüzeyi yıldız gökyüzünü yansıttı; kabul edilmek istenmeyen arzuları da.\nYalanlar ateşe atıldı, geride kalanın Hakikat olduğu söylenemez."
  },
  Stage_146233_Name = {
    Text = "Donmamış Ay"
  },
  Stage_146234_Desc = {
    Text = "Efsaneye göre, Hades Orpheus'a asla geri dönmemesini tembih etti; dönerse sevgilisini sonsuza dek kaybedeceğini söyledi.\nAma sevgilisinin Çağrı'sına yüreği dayanıp aldırmayabilseydi, onu bulmak için çırpınarak liri kucağında ölü ırmağını geçer, karanlık vadilerden geçer, karanlık yeraltı dünyasına girer miydi?"
  },
  Stage_146234_Name = {
    Text = "Geriye Baktı"
  },
  Stage_146235_Desc = {
    Text = "Kar fırtınası gelinen yolu kapattı, bir de yabancı bir yol arkadaşı getirdi.\nKaranlığın derinliklerinden hışırtılar yükseldi; sanki tüm kar dağı, içine yanlışlıkla girenleri gözetliyordu."
  },
  Stage_146235_Name = {
    Text = "Yedinci Yolcu"
  },
  Stage_146236_Desc = {
    Text = "Yol arkadaşı aynı zamanda Öncü'dür; o sizden çok önce kar sınırına ulaştı.\nYüzleş, en Başla'dan beri, bu kaçılması imkânsız bir varlıktı."
  },
  Stage_146236_Name = {Text = "Öncü"},
  Stage_146237_Desc = {
    Text = "Pelerin kar fırtınasıyla açıldı, uzun süredir saklanan sır sonunda Açılan Kanatlar'ını sergiledi.\nBazı Tüyler uçmak için değil, başka amaçlarla doğar."
  },
  Stage_146237_Name = {
    Text = "Yuvadan Ayrılış Günü"
  },
  Stage_146238_Desc = {
    Text = "Kar fırtınası gelinen yolu kapattı, bir de yabancı bir yol arkadaşı getirdi.\nKaranlığın derinliklerinden hışırtılar yükseldi; sanki tüm kar dağı, içine yanlışlıkla girenleri gözetliyordu."
  },
  Stage_146238_Name = {
    Text = "Yedinci Yolcu"
  },
  Stage_146239_Desc = {
    Text = "İnsanlar yiyeceği, yakıtı, ipleri ve oksijeni sayıp döktü; ama kimse Sırt Çantaları'nın içine saklanan dilekleri tartmadı."
  },
  Stage_146239_Name = {
    Text = "Sırt Çantaları"
  },
  Stage_146240_Desc = {
    Text = "Ateşin ışığı herkesin yüzünü aydınlattı; içlerinde sakladıkları dilekleri de.\nGece henüz bitmemişken, bir kez daha huzurla uyuyalım."
  },
  Stage_146240_Name = {
    Text = "Şömine Başında, Karanlıktan Sonra"
  },
  Stage_146241_Desc = {
    Text = "O İyi Geceler'e usulca girme."
  },
  Stage_146241_Name = {
    Text = "İyi Geceler"
  },
  Stage_146242_Desc = {
    Text = "Yol arkadaşı aynı zamanda Öncü'dür; o sizden çok önce kar sınırına ulaştı.\nYüzleş, en Başla'dan beri, bu kaçılması imkânsız bir varlıktı."
  },
  Stage_146242_Name = {Text = "Öncü"},
  Stage_146243_Desc = {
    Text = "Doğru sözler Tanrı'nın karnını yarmaya yetmez.\nBu yüzden aldatan ve aldatılan, Karanlık'ta bir arada oturup dönüş yolunu Parçala'yan bir yalan ördüler."
  },
  Stage_146243_Name = {
    Text = "Yalancılar Paktı"
  },
  Stage_146244_Desc = {
    Text = "Pelerin kar fırtınasıyla açıldı, uzun süredir saklanan sır sonunda Açılan Kanatlar'ını sergiledi.\nBazı Tüyler uçmak için değil, başka amaçlarla doğar."
  },
  Stage_146244_Name = {
    Text = "Yuvadan Ayrılış Günü"
  },
  Stage_146245_Desc = {
    Text = "O, artık bir daha bulamayacağı, kendisine ait olması gereken Bahar'dı."
  },
  Stage_146245_Name = {
    Text = "Bir Bahar Daha"
  },
  Stage_146246_Desc = {
    Text = "Doğru sözler Tanrı'nın karnını yarmaya yetmez.\nBu yüzden aldatan ve aldatılan, Karanlık'ta bir arada oturup dönüş yolunu Parçala'yan bir yalan ördüler."
  },
  Stage_146246_Name = {
    Text = "Yalancılar Paktı"
  },
  Stage_146247_Desc = {
    Text = "O İyi Geceler'e usulca girme."
  },
  Stage_146247_Name = {
    Text = "İyi Geceler"
  },
  Stage_146248_Desc = {
    Text = "Sofraya oturanların hepsi geldi; uykudaki Tanrı sonunda güldü.\nSiz hiçbir zaman ziyafete gelen Misafir değildiniz."
  },
  Stage_146248_Name = {
    Text = "Ziyafetteki Konuklar"
  },
  Stage_146249_Desc = {
    Text = "Yedi hazine her biri kendi yerine döndü; Yedi Kader İpi de sonunda aynı son noktaya ulaştı."
  },
  Stage_146249_Name = {
    Text = "Yedi Kader İpi"
  },
  Stage_146250_Desc = {
    Text = "Kar dağının tek bir kuralı vardır: Ne duyarsan duy, Cevap Verme."
  },
  Stage_146250_Name = {
    Text = "Cevap Verme"
  },
  Stage_146251_Desc = {
    Text = "Gökyüzünden en uzak yer, ayakların altındaki şiir ve uzaklıktır.\nMucize arzulayanların gökyüzüne bakacak vakti var mıdır acaba?"
  },
  Stage_146251_Name = {
    Text = "Karla Mahsur Kalan"
  },
  Stage_146253_Desc = {
    Text = "Kuş sonunda diğer kuşu buldu.\nBugün uzaklara gidiyoruz, dönüş zamanını sormuyoruz."
  },
  Stage_146253_Name = {
    Text = "Bugün Kuşlar Göç Eder"
  },
  Stage_146254_Desc = {
    Text = "Yedi hazine her biri kendi yerine döndü; Yedi Kader İpi de sonunda aynı son noktaya ulaştı."
