  },
  Stage_146255_Desc = {
    Text = "Yedi Kurban, yedi kaide, dünyanın başlangıç noktasına açılan bir Kapı.\nDilekler hiçbir zaman bedava bir armağan değildi."
  },
  Stage_146255_Name = {
    Text = "Dileksiz Zirve"
  },
  Stage_146355_Desc = {
    Text = "Uzun bir Rüya eninde sonunda dağılacak.\nHerkesin özlem duyduğu, herkesin arzuladığı, herkesin Yukarı Bakış ile baktığı, herkesin duraksadığı…\nRüyanın sonunda, hepsi ebedi Kül Kalıntıları'na dönüşecek."
  },
  Stage_146355_Name = {Text = "Uzun Rüya"},
  Stage_146724_Desc = {
