  Stage_146928_Desc = {
    Text = "Düşkün prensesin bir şövalye tarafından kurtarılması, herkesin bildiği geleneksel bir hikayedir."
  },
  Stage_146928_Name = {Text = "Prenses"},
  Stage_146929_Desc = {
    Text = "Ejderha uyandı, nefret yeniden alevlendi. Canavarın nefesi kayaların arasından fışkırdı, savaşın zehiri alevler içinde yandı ve hâlâ sönmedi.\nYer gürleyen bir şimşek gibi inledi."
  },
  Stage_146929_Name = {
    Text = "Ejder Yuvası"
  },
  Stage_146930_Desc = {
    Text = "Şövalye yabancı bir yola çıktı, ıssız ovalar ve tepeler aşarak ilerledi; yalnızca gölgesi eşlik etti.\nBelki çoktan ölmüştü, ama kimse tanık olmadığından, o da unuttu.\nDünya bu kadar sessiz ve derindi."
  },
  Stage_146930_Name = {Text = "Mezar"},
  Stage_146931_Desc = {
    Text = "Kırk gün kırk gece yağmur yağdı yeryüzüne; devam edemiyoruz, yine de devam edeceğiz."
  },
  Stage_146931_Name = {
    Text = "Elma Adası"
  },
  Stage_146932_Desc = {
    Text = "Ejderha uyandı, nefret yeniden alevlendi. Canavarın nefesi kayaların arasından fışkırdı, savaşın zehiri alevler içinde yandı ve hâlâ sönmedi.\nYer gürleyen bir şimşek gibi inledi."
  },
  Stage_146932_Name = {
    Text = "Ejder Yuvası"
  },
  Stage_146933_Desc = {
    Text = "O, cennet bahçesinin kökü ve çiçeğidir; dünyadaki tüm arzuların tacı, tükenmez bir bolluktur.\nKadehindeki şarabı iç, en çok arzuladığın şeyi göreceksin."
  },
  Stage_146933_Name = {
    Text = "Kutsal Kâse"
  },
  Stage_146934_Desc = {
    Text = "Ejderha uyandı, nefret yeniden alevlendi. Canavarın nefesi kayaların arasından fışkırdı, savaşın zehiri alevler içinde yandı ve hâlâ sönmedi.\nYer gürleyen bir şimşek gibi inledi."
  },
