  Stage_20089_Name = {
    Text = "Altın Baş"
  },
  Stage_20090_Desc = {
    Text = "Salon, Cité’nin en önde gelen sanat etkinliğidir.\nBurada, meçhuller başarıya, meşhurlar sonsuzluğa açlık duyar."
  },
  Stage_20090_Name = {
    Text = "Bayan Mercan'ın Ölümü"
  },
  Stage_20091_Desc = {
    Text = "Cevap denizin kalbinde yatıyor."
  },
  Stage_20091_Name = {Text = "Orta Deniz"},
  Stage_20092_Desc = {
    Text = "Ernst Claudel bir zamanlar Besançon’un lorduydu.\nBugün bile aile, bölgede hatırı sayılır bir prestije sahiptir."
  },
  Stage_20092_Name = {
    Text = "Mektupla Kucaklaşma"
  },
  Stage_20426_Desc = {
    Text = "Son kaçınılmaz. Ne kadar Zor denersen dene, o ne kadar çırpınırsa çırpınsın, geçmiş değiştirilemez."
  },
  Stage_20426_Name = {
    Text = "Görkemli Son"
  },
  Stage_20427_Desc = {
    Text = "Rüyalar her zaman tatlı değildir; tıpkı hiçbir melodinin sonsuza dek çalmaması gibi."
  },
  Stage_20427_Name = {Text = "Son Perde"},
  Stage_20428_Desc = {
    Text = "Kral, yüce tahtında hapsedilmiş.\nDünya dönüp değişse de onun Ağıt’ı değişmeden kalır."
  },
  Stage_20428_Name = {
    Text = "Onun Krallığı"
  },
  Stage_20429_Desc = {
    Text = "Hafızanın parçaları arasında amaçsızca dolaşıyor.\nHabersiz, hissiz, sonsuza dek tekrar ederek..."
  },
  Stage_20429_Name = {
    Text = "Hafıza Bariyeri"
  },
  Stage_20430_Desc = {
    Text = "Labirentin sonunda ne var? Gün ışığı, Karanlık mı, yoksa sınırsız bir boşluk mu?\nCevabı kendi bulmak zorunda."
  },
  Stage_20430_Name = {
    Text = "Labirentin Sonu"
  },
  Stage_20431_Desc = {
    Text = "Yavru, daha çok yavru, dinmeyen bir yavru seli...\nOnlar onun tek sevgilisi."
  },
  Stage_20431_Name = {
    Text = "Kovan Zihni"
  },
  Stage_20432_Desc = {
    Text = "Sana ait olmayan bir kapıyı asla açma."
  },
  Stage_20432_Name = {Text = "Kapı"},
  Stage_20433_Desc = {
    Text = "Rüyalar her zaman tatlı değildir; tıpkı hiçbir melodinin sonsuza dek çalmaması gibi."
  },
  Stage_20433_Name = {Text = "Son Perde"},
  Stage_20434_Desc = {
