  },
  Stage_20434_Name = {
    Text = "Mektupla Kucaklaşma"
  },
  Stage_20435_Desc = {
    Text = "Yapılabilecek her şeyi yaptı. Şimdi, yeni bir melodi bestelemek zamana kalmış."
  },
  Stage_20435_Name = {
    Text = "Yeni Bir Balad"
  },
  Stage_20436_Desc = {
    Text = "Saklamaya değer bir hafıza mı, yoksa unutulması imkânsız bir rüya mı?"
  },
  Stage_20436_Name = {
    Text = "Geçmişin İplikleri"
  },
  Stage_20437_Desc = {
    Text = "Yavru, daha çok yavru, dinmeyen bir yavru seli...\nOnlar onun tek sevgilisi."
  },
  Stage_20437_Name = {
