  },
  Stage_20438_Desc = {
    Text = "Rüyalar her zaman tatlı değildir; tıpkı hiçbir melodinin sonsuza dek çalmaması gibi."
  },
  Stage_20438_Name = {Text = "Son Perde"},
  Stage_20439_Desc = {
    Text = "Bu, aranızdaki bir sır—ruhlarınıza dağlanmış, ebediyete taşınan."
  },
  Stage_20439_Name = {
    Text = "Rüya ya da İdeal"
  },
  Stage_20440_Desc = {
    Text = "Patlamadan sonraki dünya Karanlık tarafından yutulmuş. Ruh Alanı’nda sürükleniyorsun; seni ve Erica’yı neyin beklediğinden emin değilsin."
  },
  Stage_20440_Name = {
    Text = "Ses Böyle Buyurdu"
  },
  Stage_20441_Desc = {
    Text = "Bir başka rüya, geçmişten bir başka parça—bu kez Erica’yı etten ve kandan bir bedende görüyorsun."
  },
  Stage_20441_Name = {
    Text = "Testi Başlat"
  },
  Stage_20442_Desc = {
    Text = "Patlamadan sonraki dünya Karanlık tarafından yutulmuş. Ruh Alanı’nda sürükleniyorsun; seni ve Erica’yı neyin beklediğinden emin değilsin."
