  Stage_20697_Desc = {
    Text = "Her an birileri ölür; tıpkı her an birilerinin doğması gibi.\nYalnızca gölgeler farklıdır. Zaman tarafından yutulmuş, bu ıstırap diyarına zincirlenmişlerdir.\nSonsuza dek, ne diri ne ölü."
  },
  Stage_20697_Name = {
    Text = "Gölge İlahisi"
  },
  Stage_20698_Desc = {
    Text = "Tanrı, onların acıya tahammül etmek ve son damlasına dek kanlarının akıtılmak için doğduğunu söyledi.\nNasıl güneş doğmak, yağmur yağmak zorundaysa.\nHer şey olması gerektiği gibidir."
  },
  Stage_20698_Name = {
    Text = "Acı Yağmur"
  },
  Stage_20699_Desc = {
    Text = "Zaferin mutlak üstünlüğü için yürüyoruz.\nMükemmel bir ölüm için yaşıyoruz."
  },
  Stage_20699_Name = {Text = "Uzaklardan"},
  Stage_20700_Desc = {
    Text = "Buradaki tek canlı odur, gördüğü her şey üzerinde hüküm sürer.\n—O, yüce kraldır."
  },
  Stage_20700_Name = {
    Text = "Yaban Hayvanı Krallığı"
  },
  Stage_20701_Desc = {
    Text = "Yaşamla ölüm arasındaki sınırı aşar, mezar taşlarının ötesinde yeniden kavuşurlar.\nYüz yüze, el ele, nefesleri çürümenin kokusunu taşır."
  },
  Stage_20701_Name = {
    Text = "Yalnız Kavuşma"
  },
  Stage_20702_Desc = {
    Text = "Biz böceklerin, kemiklerin ve gözyaşlarının bir bileşimiyiz.\nBu gece burada tek bir amaç için toplanıyoruz—sayısız gökkuşağıyla akan nehri seyretmek için."
  },
  Stage_20702_Name = {
    Text = "Kafatası Avı Toplantısı"
  },
  Stage_20703_Desc = {
