  },
  Stage_22313_Desc = {
    Text = "Gelgitler çekilir; anılar dalga dalga geri gelir.\nDolunay yükselmeden önce, her şey yeniden kıpırdanır."
  },
  Stage_22313_Name = {
    Text = "Gözler Açık"
  },
  Stage_23624_Desc = {
    Text = "Bazıları macera için doğar; bazıları kendini romantizmin kılığına bürür.\nSonunda, herkes kendi Hikâyesi’nin yönetmenidir."
  },
  Stage_23624_Name = {
    Text = "Andy: Johnson'ın Gücü"
  },
  Stage_23625_Desc = {
    Text = "Herkes bir Hikâye gizler. Herkes onu anlatmayı arzulamaz."
  },
  Stage_23625_Name = {
    Text = "Öykü Avcısı"
  },
  Stage_23626_Desc = {
    Text = "Takas, alışverişlerin en doğalıdır."
  },
  Stage_23626_Name = {
    Text = "Tüccarın Cömertliği"
  },
  Stage_23627_Desc = {
    Text = "En çok özlenen, en çok arzulanan dileğin ifadesini beraberinde getirir."
  },
  Stage_23627_Name = {
    Text = "En Çok Özlenen"
  },
  Stage_23628_Desc = {
    Text = "En nadide çiçekler, en güzel şiirlere hayat verir."
  },
  Stage_23628_Name = {
    Text = "En Güzel Çiçek"
  },
  Stage_23629_Desc = {
    Text = "En kusursuz son… Belki de o kadar kusursuz değildir. Ama en azından şimdilik, herkes sonucu gülümseyerek karşılar."
  },
  Stage_23629_Name = {
    Text = "Mükemmel Final"
  },
  Stage_23630_Desc = {
    Text = "En görkemli görüş alanı, en kıymetli dilekleri taşır."
  },
  Stage_23630_Name = {
    Text = "Büyük Serap"
  },
