  Stage_24183_Name = {
    Text = "Kırmızı Madam Yargısı"
  },
  Stage_24184_Name = {
    Text = "Blossom of Sludge Trial"
  },
  Stage_24423_Desc = {
    Text = "Londinium’un hiçbir vatandaşı, taze demlenmiş bir fincan çayı geri çevirmez.\nBir nehir yılanı oolongu bile olsa."
  },
  Stage_24423_Name = {
    Text = "Yedi Solungaçlı İksir"
  },
  Stage_24424_Desc = {
    Text = "Kader tarafından seçilen herkes, kendisinin istisna olduğuna inanır.\nKader, olasılıkla alay eder."
  },
  Stage_24424_Name = {
    Text = "Kaderin Mahkûmu"
  },
  Stage_24425_Desc = {
    Text = "Şak.\nEski hayatıyla tüm bağlarını koparmaya yemin etti.\nTıpkı bir kurdeleyi tertemiz ikiye ayırmak gibi."
  },
  Stage_24425_Name = {
    Text = "Sorel İçin"
  },
  Stage_24426_Desc = {
    Text = "Yine, yeniden, merhametin esiri olur ve kendini başaşağı onun ruhuna bırakırsın."
  },
  Stage_24426_Name = {
    Text = "Düşen Hüküm"
  },
  Stage_24427_Desc = {
    Text = "Hikâyenin şafağında, görkemli bir ölüme tanık olursun.\nBu bir başlangıçtır, ama sondan çok uzaktır."
  },
  Stage_24427_Name = {
    Text = "İçki Şarkısı"
  },
  Stage_24428_Desc = {
    Text = "Kızın adı Sorel; köyün gururudur.\nİtaatkâr ve lekesiz, beyazlar içinde, gerçek bir hanımefendi gibi küçük adımlarla yürür.\nYine de o hanımefendilerin aksine, asla rüya görmez."
  },
  Stage_24429_Desc = {
    Text = "Mantık, viski gibidir: Fazlası faydasını yitirir."
  },
  Stage_24429_Name = {
    Text = "Maskeli Armoni"
  },
  Stage_24430_Desc = {
    Text = "Onun titiz yetiştirişi altında, hırsın kanseri sonunda açan güller gibi yayılıp serpildi."
  },
  Stage_24430_Name = {
    Text = "Altın Kızıl Şölen"
  },
  Stage_24431_Desc = {
    Text = "Şapırt. Şapırt.\nGölgelerde kıvranır, kendi aramızda mırıldanırız.\nEtli bedenler, ay ışığı altında kıvrıla kıvrıla tuzlu gözyaşlarından izler sürükler."
  },
  Stage_24431_Name = {Text = "Yumurta"},
  Stage_24432_Desc = {
    Text = "Scone’lar, makaronlar ve fokurdayan sıcak kakao...\nHizmetçinin Dileği basittir: biraz daha iyi yemek. Ve sonra, biraz daha iyi."
  },
  Stage_24432_Name = {
    Text = "Hizmetçinin Dileği"
  },
  Stage_24433_Desc = {
    Text = "Sakının, sakının.\nHepinizin hayran olduğu hanımefendi, gerçek bir hanımefendi değildir.\nAma kimin umurunda?"
  },
  Stage_24433_Name = {
    Text = "Hanımefendi Rehberi"
  },
  Stage_24434_Desc = {
    Text = "Gül, ince başını çalan çanın sesine eğer; akbaba, kokuşmuş çiçeklerin arasında kaybolur.\nKimse şarkı söylemez. Kimse konuşmaz. Onun ölümüyle birlikte dünyadan ana renk çekilir."
  },
  Stage_24434_Name = {
    Text = "Gül Cenazesi"
  },
  Stage_24435_Desc = {
    Text = "Pınarları kurutana dek tüketir, masum kuşları boğar.\nAltın rüzgârlar getirir; tarlaların üzerinden kayan göktaşları gibi süpürür geçer.\nDünyayı arzuyla kutsal alev içinde bırakır, sonra da küle çevirir."
  },
  Stage_24435_Name = {
    Text = "Kamelya Hanımefendisi"
  },
  Stage_24439_Desc = {
    Text = "Sakının, sakının.\nHepinizin hayran olduğu hanımefendi, gerçek bir hanımefendi değildir.\nAma kimin umurunda?"
  },
  Stage_24439_Name = {
    Text = "Hanımefendi Rehberi"
  },
