  },
  Stage_24528_Desc = {
    Text = "Ne olursa olsun, ne kadar çok şey değişirse değişsin—çağrın her zaman duyulacak."
  },
  Stage_24528_Name = {
    Text = "Elveda Değil"
  },
  Stage_24529_Desc = {
    Text = "Bir kez, iki kez, üç kez—Sisifos kayasını iter; ulaşılamayan bir zirveye boşuna tırmanır durur."
  },
  Stage_24529_Name = {Text = "Sisifos"},
  Stage_24530_Desc = {
    Text = "Bir zamanlar tanıdık olan kız artık bir yabancıya dönüşmüştür. Bu soğuk, uzak siluet—gerçekten tanıdığın Ramona olabilir mi?"
  },
  Stage_24530_Name = {
    Text = "Hepsi Birden"
  },
  Stage_24531_Desc = {
    Text = "Sıradan bir gün, olağanüstü bir rüya ile başlar."
  },
  Stage_24531_Name = {
    Text = "Yağmur Gibi Gözyaşları"
  },
  Stage_24532_Desc = {
    Text = "Bir zamanlar tanıdık olan kız artık bir yabancıya dönüşmüştür. Bu soğuk, uzak siluet—gerçekten tanıdığın Ramona olabilir mi?"
  },
  Stage_24532_Name = {
