  Stage_35099_Desc = {
    Text = "\"Sus—tahmin et, gözlerin aracılığıyla ne gördüm?\"\nKoruyucu, Aurita’yı korkutup ağlattıktan sonra, Lotan neredeyse Koruyucu’nun odasındaki Dördüncü Duvar’ı yerle bir ediyordu; çünkü Aurita’nın ağlaması fazlasıyla tedirgin ediciydi."
  },
  Stage_35099_Name = {
    Text = "IX: Dördüncü Duvar"
  },
  Stage_35100_Desc = {
    Text = "\"Seyircinin hikâyede tümüyle kaybolmasına izin verme; sahnede olup biteni çözümleyip eleştirmeye zorla onları.\"\nBu kuram hakkında Aurita’nın söyleyeceği şuydu: Aurita kimse tarafından azarlanmak istemiyor! Aurita sadece herkesle arkadaş olmak istiyor!"
  },
  Stage_35100_Name = {
    Text = "VIII: Yabancılaştırma Etkisi"
  },
  Stage_35129_Desc = {
    Text = "O, rüyalarla gerçeğin iç içe geçtiği sınırdır—gece göğüne bakan her ruhun derinliklerinde yaşayan yansımadır."
  },
  Stage_35129_Name = {
    Text = "Çarpık Yıldızlar"
  },
  Stage_35129_StageInitStateText = {
    Text = "Deniz Kabusu"
  },
  Stage_35130_Desc = {Text = "Hazır."},
  Stage_35130_Name = {
    Text = "İçselleştirilmiş Alev"
  },
  Stage_35571_Desc = {
    Text = "Aurita’nın arkadaşı olduğun için, sana tüm arkadaşlarını tanıtmak istiyor."
  },
  Stage_35571_Name = {
    Text = "Arkadaş Koleksiyonu"
  },
  Stage_35572_Desc = {
    Text = "Aurita’nın arkadaşı olduğun için, sana tüm arkadaşlarını tanıtmak istiyor."
  },
  Stage_35572_Name = {
    Text = "Arkadaş Koleksiyonu"
  },
  Stage_35573_Desc = {
    Text = "Aurita’nın arkadaşı olduğun için, sana tüm arkadaşlarını tanıtmak istiyor."
  },
  Stage_35573_Name = {
    Text = "Arkadaş Koleksiyonu"
  },
  Stage_35574_Desc = {
    Text = "Aurita senden hoşlanıyor ve sıradan günlerini paylaşabileceği bir arkadaş olmanı diliyor."
  },
  Stage_35574_Name = {
    Text = "Sessiz Gün"
  },
  Stage_35575_Desc = {
    Text = "Herkes yanında olduğunda, Aurita’nın uykuya dalmaktan hiç Dehşet’i yok."
  },
  Stage_35575_Name = {
    Text = "Sualtı Sarayı"
  },
  Stage_35843_Name = {
    Text = "Lady of the Depths Trial"
  },
  Stage_35857_Desc = {
    Text = "Yıldızlar, ait oldukları yere çekildi; insan kavrayışının ötesinde yollarla haberleşiyor, zamanın akışını ve geçmiş yılların ışığını yakalayan görünmez bir ağ dokuyorlar."
  },
  Stage_35857_Name = {
    Text = "Bilinmeyen Yıldız Yolu"
  },
  Stage_36125_Desc = {
    Text = "Lütuflanmamış çocuk, denizin içinde ilahiler terennüm eder.\nSus—sessiz ol. Onun Ebedi Uykuya Dalış’ını sakın bozma."
  },
  Stage_36125_Name = {
