  Stage_36614_Desc = {
    Text = "Şehvete batmak, arzuya teslim olmak...\n—Ve sonra?\nHerkese ibret olsun diye ebedî alevlerle yüzleş.\n—Ah."
  },
  Stage_36614_Name = {
    Text = "Ölüm, Bal Şarabı ve Şarkı Gecesi"
  },
  Stage_36615_Desc = {
    Text = "Dört evlilik ve dört cenaze—Wanda’nın ölümlü dünyadaki \"duygusal hayatı\" nın tek dipnotu."
  },
  Stage_36615_Name = {
    Text = "Dört Düğün"
  },
  Stage_36616_Desc = {
    Text = "Şehvete batmak, arzuya teslim olmak...\n—Ve sonra?\nHerkese ibret olsun diye ebedî alevlerle yüzleş.\n—Ah."
  },
