  Stage_36619_Name = {
    Text = "Ölüm, Bal Şarabı ve Şarkı Gecesi"
  },
  Stage_36620_Desc = {
    Text = "Kraliçe yüce tahtına kurulmuş.\nYanında sonu gelmez hazineler, sınırsız zenginlik ve batmış kozmik harabelerden bir iz var."
  },
  Stage_36620_Name = {
    Text = "Sürgün Kraliçe"
  },
  Stage_36621_Desc = {
    Text = "Felaket’ten önce başkent, onun hırsının ve Arzu’sunun bir uzantısıydı.\nFelaket’ten sonra başkent, gece ve yalnızlığın zindanına dönüştü."
  },
  Stage_36621_Name = {Text = "Kavalcı"},
  Stage_36887_Name = {
    Text = "Queen of Thorns Trial"
  },
  Stage_38756_Desc = {
    Text = "Gözlerini kapar ve evrenin boşluğunda amaçsızca süzülür.\nBir yıl, yüz yıl... Sonunda bir gün, kendi kendine fısıldar: \"Sorun değil. Bırak, hakikati ve yalanı ben tanımlayayım.\"\nKraliçe ve onun ölümsüz şehri—Isarawu, böylece evrenin engin galaksileri arasında askıda kalır.\nOnun hikâyesini benimle paylaşır ki Isarawu’nun Hikâye sonsuza dek hatırlansın."
  },
  Stage_38756_Name = {
    Text = "Geçici Bir Anı: Anımsama Bölüm VI"
  },
