  Stage_38762_Name = {
    Text = "Geçici Bir Anı: Anımsama·Bölüm I"
  },
  Stage_38763_Desc = {
    Text = "Isarawu yok oldu, sanki hiç var olmamış gibi.\nTüm sokaklar ve insanlar birer düş'tü. Onlar, onun düşlerinden doğmuş, günbegün şekil kazanmış, sonra da:\n\"Bang—\"\nDüş sona erdi. O, Isarawu'yu görmek için gözlerini hiç açmadı; tıpkı kendisini görmek için de hiç açmadığı gibi."
  },
