  Stage_43506_Desc = {
    Text = "Elveda, dedi dev.\nYenilmez ve yok edilemez olduğum tarihe geri döneceğim.\nBen ölümsüzüm."
  },
  Stage_43506_Name = {
    Text = "Batık Borazan"
  },
  Stage_43508_Desc = {
    Text = "Ey göz ardı edilen, nereye gidiyorsun?\n—Issızlığın uzak diyarına. Orada yıldızlar ve ay suskun, okyanus hareketsizdir.\nYalnızca sen ve ben kalırız dünyada."
  },
  Stage_43508_Name = {
    Text = "Sığınaksız Deniz"
  },
  Stage_43509_Desc = {
    Text = "Elveda, dedi dev.\nYenilmez ve yok edilemez olduğum tarihe geri döneceğim.\nBen ölümsüzüm."
  },
  Stage_43509_Name = {
    Text = "Batık Borazan"
  },
  Stage_43510_Desc = {
    Text = "Kahraman ve yoldaşları altın bir denizde yelken açar.\nAynı yaraları taşırlar, aynı ezgiyi söylerler ve ölümle topraktan yeniden doğuşu birlikte göğüslerler."
  },
  Stage_43510_Name = {
    Text = "Altın Nakarat"
  },
  Stage_43512_Desc = {
    Text = "Elveda, dedi dev.\nYenilmez ve yok edilemez olduğum tarihe geri döneceğim.\nBen ölümsüzüm."
  },
  Stage_43512_Name = {
    Text = "Batık Borazan"
  },
  Stage_44196_Desc = {
    Text = "Ey ahmaklar, alevleri siz yaktınız ve umutla kurtuluşu küle çevirdiniz.\nŞimdi söyleyin, ölümün zifiri karanlığında çırpınırken, bu kendiniz ilan ettiğiniz Adalet nasıl bir tat bırakıyor?"
  },
  Stage_44196_Name = {
    Text = "Tövbe: Serpilme Bölüm VI"
  },
  Stage_44197_Desc = {
