  Stage_44551_Desc = {
    Text = "Merhametli Baba, lütfen beni bağışla. Telafi etmeme ve günahlarımın kefaretini ödememe izin ver."
  },
  Stage_44551_Name = {
    Text = "Bizim Çöküşümüz"
  },
  Stage_44552_Desc = {
    Text = "Toz dindi. Suçlular yargıyla yüzleşecek; yürümeye devam edenler yoluna devam edecek.\nYarın yeni bir gün."
  },
  Stage_44552_Name = {
    Text = "Tutuşan Beyaz Umut"
  },
  Stage_44553_Desc = {
    Text = "Sıradan bir öğleden sonra olacaktı—ama Mythag’ın Koruyucusu için sıradan olan şey, düpedüz bir lükstür."
  },
  Stage_44553_Name = {Text = "Tövbe"},
  Stage_44554_Desc = {
    Text = "Arındırma, arındırma... Bu bir delinin hezeyanları mı, yoksa çarpılmış bir inanç mı?"
  },
  Stage_44554_Name = {
    Text = "Kan Mührü"
  },
  Stage_44555_Desc = {
    Text = "Alevler tarafından yutuldular, akıldan soyuldular."
  },
  Stage_44555_Name = {
    Text = "Öfkenin Çılgınlığı"
  },
  Stage_44556_Desc = {
    Text = "Başkalarında ne varsa, onlarda da olmalı; başkalarında ne yoksa, onlar daha da fazlasına sahip olmalı—ne kadar nafile, ne kadar saçma olursa olsun."
  },
  Stage_44556_Name = {
    Text = "Kıskançlığın Kılıcı"
  },
  Stage_44557_Desc = {
    Text = "Dur, dinlen, yeterince didindin. Uzan, uyu, seni azarlamaya kimsenin yüreği elvermez."
  },
  Stage_44557_Name = {
    Text = "Yorgunluğa Teslim Ol"
  },
  Stage_44558_Desc = {
    Text = "Geldiğin fitil yolundan güçlükle geri dönersin, yalnızca açlıktan kıvranan dişlerle karşılaşmak için."
  },
  Stage_44558_Name = {
    Text = "Açlığı Doyur"
  },
  Stage_44559_Desc = {
    Text = "Yansımaya baktığında gördüğün bir hayalet mi, yoksa gerçek arzun mu?"
  },
  Stage_44559_Name = {
    Text = "Günahı Arındır"
  },
  Stage_44560_Desc = {
    Text = "Merhametli Baba, lütfen beni bağışla. Telafi etmeme ve günahlarımın kefaretini ödememe izin ver."
  },
