  Stage_45411_Name = {
    Text = "Veda Öpücüğü"
  },
  Stage_46169_Desc = {
    Text = "Tüm olasılıkları ezberledi, yine de herhangi bir ilahiyat öğrencisi kadar şaşkındı.\nÇünkü delilik öngörüye meydan okur. Ne yazık ki, dünyanın gerçek normu odur."
  },
  Stage_46169_Name = {
    Text = "Büyük Şlem Ahdi"
  },
  Stage_46170_Desc = {
    Text = "Tüm olasılıkları ezberledi, yine de herhangi bir ilahiyat öğrencisi kadar şaşkındı.\nÇünkü delilik öngörüye meydan okur. Ne yazık ki, dünyanın gerçek normu odur."
  },
  Stage_46170_Name = {
    Text = "Büyük Şlem Ahdi"
  },
  Stage_46171_Desc = {
    Text = "Lanet, seni ebedî kış uykusuna mahkûm bir yılana çevirir.\nGöbek bağın kadar eskidir."
  },
  Stage_46171_Name = {
    Text = "Lanetli Bağ"
  },
  Stage_46172_Desc = {
    Text = "Kız çocuk bir zamanlar Mason’dı.\nYakında Odysseus gibi olacak—hiç kimse.\nVe sonra, çok geçmeden, herkes olacak."
  },
  Stage_46172_Name = {Text = "\"Köken\""},
  Stage_46173_Desc = {
    Text = "Lanet, seni ebedî kış uykusuna mahkûm bir yılana çevirir.\nGöbek bağın kadar eskidir."
  },
  Stage_46173_Name = {
    Text = "Lanetli Bağ"
  },
  Stage_46174_Desc = {
    Text = "Burada son bulur. Benimle son bulur.\nRabbini sınama."
  },
  Stage_46174_Name = {
    Text = "Burada Sona Erer"
  },
  Stage_46175_Desc = {
    Text = "Yıllar boyunca hacılar, karla örtülü Sıradağlar arasında bir geçit oydular, gerçekliği yerinde çivileyerek.\nÖylece kımıldamadan dururlar, ağızları açık, sanki sonsuz bir kükreyiş içinde kilitlenmiş gibi—"
  },
  Stage_46175_Name = {
    Text = "Hacının İlahisi"
  },
  Stage_46176_Desc = {
    Text = "Lanet, seni ebedî kış uykusuna mahkûm bir yılana çevirir.\nGöbek bağın kadar eskidir."
  },
  Stage_46176_Name = {
    Text = "Lanetli Bağ"
  },
  Stage_46177_Desc = {
    Text = "Tüm olasılıkları ezberledi, yine de herhangi bir ilahiyat öğrencisi kadar şaşkındı.\nÇünkü delilik öngörüye meydan okur. Ne yazık ki, dünyanın gerçek normu odur."
  },
  Stage_46177_Name = {
    Text = "Büyük Şlem Ahdi"
  },
  Stage_46178_Desc = {
    Text = "Kendini, dünyanın eşiğinde durup onu sahiplenmek üzereyken izledi.\nBakışını o uzun, dar gölgeye dikti ve hiçbir şey söylemedi."
  },
  Stage_46178_Name = {
    Text = "Gölge Masalı"
  },
  Stage_46179_Desc = {
    Text = "Onun komedisi eşsizdir. Uçsuz bucaksız, ıssız gecelerden, aydan ve gözyaşlarından örülüdür."
  },
  Stage_46179_Name = {
    Text = "Komediyi Beklerken"
  },
  Stage_46180_Desc = {
    Text = "Her şey hafif uykuya daldığında, yılan kıpırdanır.\nHer şey çöktüğünde, yılan yeniden dirilir."
  },
  Stage_46180_Name = {
    Text = "Uykusuz Yılan"
  },
  Stage_46181_Desc = {
    Text = "Kedi duygularını on sekiz parçaya böler ve her biri için farklı bir \"miyav\" tonu tasarlar.\nBöylece \"Açım\", \"Gel benimle oyna\", \"Beni rahat bırak\" diyebilir.\nVe bir de: \"Seni özlüyorum.\""
  },
  Stage_46181_Name = {
    Text = "Kedi Her Şeyi Bilir"
  },
  Stage_46182_Desc = {
    Text = "Yaşlı çanın çalmasıyla birlikte, hafif ve solan bir kutsama yayılır.\nMutlu tatiller. Mutlu tatiller. Mutlu tatiller."
  },
  Stage_46182_Name = {
    Text = "Altın Füg"
  },
