  Stage_46547_Desc = {
    Text = "Burada ne zaman yargıca dönüştüğünü bilmiyorum.\nAdı saklanan birini yargıladı ve onu ölüme mahkûm etti.\nSonra şu vahyi işitti: \"O kişi sensin.\"\nEvet, buradaki tüm tutsakların, yargıçların ve rahiplerin yüzü aynıdır."
  },
  Stage_46547_Name = {
    Text = "Amigdala'nın Çağrısı: Belirme Bölüm IV"
  },
  Stage_46548_Desc = {
    Text = "Cehennem, sayısız Yansıma ile kaplı boş bir odadır.\nGözlerini açmaya cesaret edemez; çünkü nereye baksa kendi solgun, dehşet içindeki yüzünü görür.\nBoşluğun bir yerinde bir ses şöyle yankılanır:\nBu bir cezalandırma. Yaşarken yalnızca tek bir kabuğun vardı; ölümde ise sayısızıyla yüzleşiyorsun."
  },
  Stage_46548_Name = {
    Text = "Aynanın Bakışı: Belirme Bölüm VI"
  },
