  },
  Stage_55142_StageInitStateText = {Text = "Son Perde"},
  Stage_55143_Desc = {
    Text = "Küçük çiçek evi, onların minik krallığıdır.\nBu mütevazı âlemde hiçbir şeyleri yoktur—ve bunu başka türlü istemezlerdi."
  },
  Stage_55143_Name = {
    Text = "Küçücük Krallık·Bölüm IV"
  },
  Stage_55144_Desc = {
    Text = "Meşhur olan şiir her şeyi getirdi; arkadaşının övgüleri karşısında kızardı. Dizeleri nihayet arkadaşını acıdan kurtarmıştı—ya da o öyle sanıyordu.\nDuymadığı şey, kötülük tohumlarının çoktan ekilmiş olduğuydu; gülleri sarmalamak ve onları imha etmek için pusuda bekliyorlardı."
  },
