  Stage_55391_Desc = {
    Text = "\"İlk gülünü, ilk şiirinle takas edeyim.\""
  },
  Stage_55391_Name = {
    Text = "Mezmur 1843"
  },
  Stage_55392_Desc = {
    Text = "Bahçe bir bulmaca, Bahar ise onun son parçası."
  },
  Stage_55392_Name = {Text = "Kalan Koku"},
  Stage_55393_Desc = {
    Text = "\"İlk gülünü, ilk şiirinle takas edeyim.\""
  },
  Stage_55393_Name = {
    Text = "Mezmur 1843"
  },
  Stage_55394_Desc = {
    Text = "Ne yas var, ne rüzgâr.\nYalnızca şiirdeki kişinin tortu mürekkebi ve bahçe için çalan ölüm çanı."
  },
  Stage_55394_Name = {
    Text = "Bahçe Ağıdı"
  },
  Stage_55395_Desc = {
    Text = "Heykel, kralın hitabetidir; sessizlik ise heykelin."
  },
  Stage_55395_Name = {
    Text = "Heykel Retoriği"
  },
  Stage_55396_Desc = {
    Text = "Bahçenin iki ucundan birbirlerine bakarlar.\nBahçenin içinde sayısız patika yatar—ona ait olan her yol, ötekine ait olan her yoldan bir sapmadır."
  },
  Stage_55396_Name = {
    Text = "Çatallanan Patikalar Bahçesi"
  },
  Stage_55397_Desc = {
    Text = "İlk cenazede kemiklere, ikincisinde zamana elveda de."
  },
  Stage_55397_Name = {
    Text = "Gecikmiş Cenaze"
  },
  Stage_55398_Desc = {
    Text = "Mükemmel şiir, okuru kendi dünyasına nüfuz ettirir.\nKlasik estetik kuramı böyle söyler."
  },
  Stage_55398_Name = {Text = "Şair"},
  Stage_55399_Desc = {
    Text = "Cité’nin çiçekleri davetlerini uzatıyor, seni bu düşe katılmaya çağırıyor."
  },
  Stage_55399_Name = {
    Text = "Çiçekler Şehri"
  },
  Stage_55400_Desc = {
    Text = "İnsanların “ev” dediği şey, kök salmış bir yalandan ibarettir."
  },
  Stage_55400_Name = {Text = "Ev"},
  Stage_55401_Desc = {
    Text = "\"İlk gülünü, ilk şiirinle takas edeyim.\""
  },
  Stage_55401_Name = {
    Text = "Mezmur 1843"
  },
  Stage_55551_Desc = {
    Text = "Bu Karlı Dağ canlıdır; geçitlerinde Ulu­ma yankılanır—kızını çağırmaktadır.\nGel, çabuk gel.\nAnne kıza mı gider, yoksa kız mı Anne’ye?\nZirvede, iki boş, aç mide sonunda buluşur."
  },
