  Stage_58392_Name = {
    Text = "Geçici Bir Anı·Bölüm II"
  },
  Stage_58393_Desc = {
    Text = "Gözlerini açtığında, dünya çözülmekteydi.\nBütün binalar çökmüş; siyah balçık göğe doğru uzanıyor; beyaz frezyalar sonsuz boşlukta çözünüyordu.\nHer şey sessizdi. Her şey uykuda gibiydi.\nYalnızca gözyaşları soğuktu; yüzüne yapışıyor, saçlarını sırılsıklam ediyordu."
  },
