  Stage_58436_Desc = {
    Text = "Sayısız yılanın onu bir ağ gibi sarıp sarmaladığını hissetti.\nUyandığında, başucunda bir Gölge duruyordu. Şöyle dedi:\n \"Nereye gidersen git, seni sileceğim—tıpkı şu an yüzümü sildiğin gibi.\""
  },
  Stage_58436_Name = {
    Text = "Soluk Hatırlama·Bölüm V"
  },
  Stage_58437_Desc = {
    Text = "Sayısız yılanın onu bir ağ gibi sarıp sarmaladığını hissetti.\nUyandığında, başucunda bir Gölge duruyordu. Şöyle dedi:\n \"Nereye gidersen git, seni sileceğim—tıpkı şu an yüzümü sildiğin gibi.\""
  },
  Stage_58437_Name = {
    Text = "Soluk Hatırlama·Bölüm IV"
  },
  Stage_58438_Desc = {
    Text = "Sayısız yılanın onu bir ağ gibi sarıp sarmaladığını hissetti.\nUyandığında, başucunda bir Gölge duruyordu. Şöyle dedi:\n \"Nereye gidersen git, seni sileceğim—tıpkı şu an yüzümü sildiğin gibi.\""
  },
  Stage_58438_Name = {
    Text = "Soluk Hatırlama·Çılgınlık"
  },
  Stage_58438_StageInitStateText = {Text = "Köken"},
  Stage_58439_Desc = {
    Text = "Sayısız yılanın onu bir ağ gibi sarıp sarmaladığını hissetti.\nUyandığında, başucunda bir Gölge duruyordu. Şöyle dedi:\n \"Nereye gidersen git, seni sileceğim—tıpkı şu an yüzümü sildiğin gibi.\""
  },
  Stage_58439_Name = {
    Text = "Soluk Hatırlama·Bölüm VI"
  },
  Stage_58440_Desc = {
    Text = "Bu, ruhunun en tiksinç parçasının nişanesi hâline geldi.\nOnunla birlikte acı çekti, onunla birlikte öldü ve bir bakıma onunla birlikte yok oldu.\nBöylece kalbi demir kesildi ve artık merhamet göstermiyor."
  },
  Stage_58440_Name = {
    Text = "Sürüngen Zihni·Bölüm III"
  },
  Stage_58441_Desc = {
    Text = "Bu, ruhunun en tiksinç parçasının nişanesi hâline geldi.\nOnunla birlikte acı çekti, onunla birlikte öldü ve bir bakıma onunla birlikte yok oldu.\nBöylece kalbi demir kesildi ve artık merhamet göstermiyor."
  },
  Stage_58441_Name = {
    Text = "Sürüngen Zihni·Bölüm II"
  },
  Stage_58442_Desc = {
    Text = "Bu, ruhunun en tiksinç parçasının nişanesi hâline geldi.\nOnunla birlikte acı çekti, onunla birlikte öldü ve bir bakıma onunla birlikte yok oldu.\nBöylece kalbi demir kesildi ve artık merhamet göstermiyor."
  },
  Stage_58442_Name = {
    Text = "Sürüngen Zihni·Bölüm I"
  },
  Stage_58443_Desc = {
    Text = "Bu, ruhunun en tiksinç parçasının nişanesi hâline geldi.\nOnunla birlikte acı çekti, onunla birlikte öldü ve bir bakıma onunla birlikte yok oldu.\nBöylece kalbi demir kesildi ve artık merhamet göstermiyor."
  },
  Stage_58443_Name = {
    Text = "Sürüngen Zihni·Çılgınlık"
  },
  Stage_58443_StageInitStateText = {Text = "Köken"},
  Stage_58444_Desc = {
    Text = "Bu, ruhunun en tiksinç parçasının nişanesi hâline geldi.\nOnunla birlikte acı çekti, onunla birlikte öldü ve bir bakıma onunla birlikte yok oldu.\nBöylece kalbi demir kesildi ve artık merhamet göstermiyor."
  },
  Stage_58444_Name = {
    Text = "Sürüngen Zihni·Bölüm VI"
  },
  Stage_58445_Desc = {
    Text = "Bu, ruhunun en tiksinç parçasının nişanesi hâline geldi.\nOnunla birlikte acı çekti, onunla birlikte öldü ve bir bakıma onunla birlikte yok oldu.\nBöylece kalbi demir kesildi ve artık merhamet göstermiyor."
  },
  Stage_58445_Name = {
    Text = "Sürüngen Zihni·Bölüm V"
  },
  Stage_58446_Desc = {
    Text = "Bu, ruhunun en tiksinç parçasının nişanesi hâline geldi.\nOnunla birlikte acı çekti, onunla birlikte öldü ve bir bakıma onunla birlikte yok oldu.\nBöylece kalbi demir kesildi ve artık merhamet göstermiyor."
  },
  Stage_58446_Name = {
    Text = "Sürüngen Zihni·Bölüm IV"
  },
  Stage_58449_Desc = {
    Text = "Yankı.\nCanı pahasına, onun hareketi O’nun salonlarında sonsuza dek yankılanır."
  },
  Stage_58449_Name = {
    Text = "Yankılar·Çılgınlık"
  },
  Stage_58449_StageInitStateText = {Text = "Köken"},
  Stage_58450_Desc = {
    Text = "Perde iner.\nBaşı dik, alçalan kırmızı kadifenin ardına çekilir."
  },
  Stage_58450_Name = {
    Text = "Perde Kapanışı·Çılgınlık"
  },
  Stage_58450_StageInitStateText = {Text = "Köken"},
  Stage_58451_Desc = {
    Text = "Bu, Dördüncü Kapı'dır.\nDördüncü Kapı'dan giren, Onların gerçek çehresini temaşa edecektir.\nKozmosu enginliği içinde görmek, kendi hiçliğini kavramaktır. Bir karıncanın ulu bir ağacı sarsabileceğini sanma."
  },
  Stage_58451_Name = {
    Text = "Bilgi Kapısı·Çılgınlık"
  },
  Stage_58451_StageInitStateText = {Text = "Köken"},
  Stage_58452_Desc = {
    Text = "Oyuncak Evi’ne hoş geldin; binlerce özdeş gülümseme seni bekliyor.\nHehe... hangisi senin eski dostundu acaba?"
  },
  Stage_58452_Name = {
    Text = "Kukla Evi·Çılgınlık"
  },
  Stage_58453_Desc = {
    Text = "Bu dünyada hiç Kapı olmadı.\nYine de özlem dolu yürekler onları dövdü: sayısız Kapı, her biri bir Paradise vaat eden.\nAma eski Kehanet fısıldar: gerçek bir Kapı yoktur.\nYeryüzünde cenneti arayanlar, onun yerine cehennemin çenesini ardına dek açacaktır."
  },
  Stage_58453_Name = {
    Text = "Kaos Kehaneti·Çılgınlık"
  },
  Stage_58454_Desc = {
    Text = "İpekten iplikler, bebeğin parmaklarından sızıp dünyanın çarklarına dolanıyor.\nTak, tıkırtı... Tek bir seğiriş, ve gerçeklik çözülüyor.\nAma boşluk uğruna sonsuz dansına zorlanan o kuklanın üstünde ne sallanıyor?"
  },
  Stage_58454_Name = {
    Text = "Kader İpleri·Çılgınlık"
  },
  Stage_58455_Desc = {
    Text = "Neşeli bölüm.\nTüm Toprak boyunca ilerlerler; meydan okuyan bedenleri görülmeye değerdir."
  },
  Stage_58455_Name = {
    Text = "Minuet·Çılgınlık"
  },
  Stage_58455_StageInitStateText = {Text = "Köken"},
  Stage_58456_Desc = {
    Text = "Bu, Üçüncü Kapı'dır.\nÜçüncü Kapı'dan giren, sığ aklın prangalarından azat olur ve böylece sınırın ötesinde yatan bilgiyi idrak edebilir."
  },
  Stage_58456_Name = {
    Text = "Akıl Kapısı·Çılgınlık"
  },
  Stage_58456_StageInitStateText = {Text = "Köken"},
  Stage_58457_Desc = {
    Text = "Dans et, dans et, hareketin hiç durmasın.\nEteklerini savur, vahşi daireler çiz—dünya bile kendi ekseninde Unutuş’a doğru savruluyor.\nZincirlerini at, bu son maskeli baloya katıl.\nKendinden geçerek dans et ve ebedi gün batımına tanık ol."
  },
  Stage_58457_Name = {
    Text = "Karnaval Dansı·Çılgınlık"
  },
  Stage_58458_Desc = {
    Text = "Sonat formu.\nBirden üç doğar; üçgenin içinde, kırpmadan bakan bir göz Toprak’ı süzer."
  },
  Stage_58458_Name = {
    Text = "Allegro·Çılgınlık"
  },
  Stage_58458_StageInitStateText = {Text = "Köken"},
  Stage_58459_Desc = {
    Text = "Kralın kehanet ettiği her şeye kavuştu—muazzam güç, sarsılmaz bir inanç. Bir zamanlar Kral’ı sorgulamanın Günahını taşıyarak, İlahi Diyar’ı karşılamaya koyuldu."
  },
  Stage_58459_Name = {
    Text = "Sadık Kalp·Çılgınlık"
  },
  Stage_58459_StageInitStateText = {
    Text = "Deniz Kabusu"
  },
  Stage_58460_Desc = {
    Text = "Bu, Beşinci Kapı'dır.\nBeşinci Kapı'dan giren, kozmosla paylaşılan yüce sırrın ortağı olur.\nTüm varlıklar, Onların varlığının çektiği tek bir nefesten ibarettir ve Onların soluğuyla geri alınacaktır."
  },
  Stage_58460_Name = {
    Text = "Birlik Kapısı·Çılgınlık"
  },
  Stage_58460_StageInitStateText = {Text = "Köken"},
  Stage_58461_Desc = {
    Text = "Elini uzatıyor—onunla dans edecek misin?\nİleri, geri; adımların yalnızca onunkini yansıtıyor.\nAvucunu kavra, ritmine uy, sakın başını eğme.\nAyaklarının altında uçurum yarılırken bile."
  },
  Stage_58461_Name = {
    Text = "Davet: Madness"
  },
  Stage_58462_Desc = {
    Text = "Bu, Altıncı Kapı'dır.\nAltıncı Kapı'dan giren, tüm dünyalar arasındaki bağ hâline gelir; on binlerce boyut boyunca ebedî varoluşu arar."
  },
  Stage_58462_Name = {
    Text = "Dünyalar Kapısı·Çılgınlık"
  },
  Stage_58462_StageInitStateText = {Text = "Köken"},
  Stage_58463_Desc = {
    Text = "Lirik bölüm.\nBeslenme, çoğalma, durmaksızın süren hayat."
  },
  Stage_58463_Name = {
    Text = "Adagio·Çılgınlık"
  },
  Stage_58463_StageInitStateText = {Text = "Köken"},
  Stage_58464_Desc = {
    Text = "Öyleyse yola koyul.\nBu yol \"Bilgelik\" e mi, yoksa \"Ahmaklık\" a mı çıkar, bunu ancak yolculuğun kendisi açığa vurabilir."
  },
  Stage_58464_Name = {
    Text = "Yola Çık: Delilik"
  },
  Stage_58464_StageInitStateText = {Text = "Köken"},
  Stage_58465_Desc = {
    Text = "Bir senfoni tek kişinin çabası değildir.\nYaylılar, tahta nefesliler, bakır nefesliler, vurmalılar.\nHer biri sıralanmış çalgı grupları, başlarını eğmiş, onun işaretini bekler."
  },
  Stage_58465_Name = {
    Text = "Büyük Düzen·Çılgınlık"
  },
  Stage_58465_StageInitStateText = {Text = "Köken"},
  Stage_58466_Desc = {
    Text = "Sesi takip ederek kürsüye adım attı.\nAdımları sakindi, duruşu vakurdu.\nOraya bir rüya yüzünden geldiğini—ve rüyanın sahibinin çoktan yitip gittiğini—kimse bilmiyordu."
  },
  Stage_58466_Name = {
    Text = "Kayıp Düşün Rehberi·Çılgınlık"
  },
  Stage_58466_StageInitStateText = {Text = "Köken"},
  Stage_58467_Desc = {
    Text = "Bu, Birinci Kapı'dır.\nBirinci Kapı'dan giren, zincirlerini kırmalı, özünü terk etmeli ve benliğini unutmalıdır.\nZira bireye bağlı bir görüş alanı, saçma hakikatin ağırlığını taşımak için fazlasıyla kırılgandır."
  },
  Stage_58467_Name = {
    Text = "Öz Kapısı·Çılgınlık"
  },
  Stage_58467_StageInitStateText = {Text = "Köken"},
  Stage_58468_Desc = {
    Text = "Bu, İkinci Kapı'dır.İkinci Kapı'dan giren, doğruyu yanlıştan ayırmaya kalkışmamalıdır.\nZira bu ayrımlar, yalnızca kural koyanların keyfîliğidir; hakikatin makamı ise her türlü bilginin ötesinde yatar."
  },
  Stage_58468_Name = {
    Text = "Hakikat Kapısı·Çılgınlık"
  },
  Stage_58468_StageInitStateText = {Text = "Köken"},
  Stage_58469_Desc = {
    Text = "Rondo formu.\nSon yola giden yönü gösterecek ve Yıkım’la yüz yüze gelecektir."
  },
  Stage_58469_Name = {
    Text = "Son Perde·Çılgınlık"
  },
  Stage_58469_StageInitStateText = {Text = "Köken"},
  Stage_58470_Desc = {
    Text = "İlahi Diyar’ın silueti Onun Gözleri’nin önünde belirdi. İlahi Diyar’ın çanlarının yankısı kulaklarında çınladı. Kral’ın kehanetini, durmaksızın yerine getirecek.\nBu sözler, hayatının engin Karanlık’ında ona Rehberlik etti."
  },
  Stage_58470_Name = {
    Text = "Varış·Çılgınlık"
  },
  Stage_58470_StageInitStateText = {
    Text = "Deniz Kabusu"
  },
  Stage_58471_Desc = {
    Text = "Kıyamet geldiğinde, dünya çıbanlarla çürüyüp kabuk bağlayacak, ve çürümenin girdabı tüm canlıları yutacaktır.\nDua et, ara, hiç var olmamış o Kurtuluş Kapısı’nı."
  },
  Stage_58471_Name = {
    Text = "Çılgın Felaket·Çılgınlık"
  },
  Stage_58472_Desc = {
    Text = "Her şeyini kaybettiği gün, sonunda yalnızca Kral’ın Lemuria halkını kurtarabileceğini idrak etti.\nO, uzaklardaki o İlahi Diyar’da, yitirdiği her şeyle yeniden kavuşmayı bekliyor."
  },
  Stage_58472_Name = {
    Text = "Sessiz Tanık·Çılgınlık"
  },
  Stage_58472_StageInitStateText = {
    Text = "Deniz Kabusu"
  },
  Stage_58473_Desc = {
    Text = "Lemuria yok oldu. Rabbimiz bu toprakla asla ilgilenmedi.\nİlahi Diyar hiç var olmadı."
  },
  Stage_58473_Name = {
    Text = "Titreme·Çılgınlık"
  },
  Stage_58473_StageInitStateText = {
    Text = "Deniz Kabusu"
  },
  Stage_58474_Desc = {
    Text = "Neden hâlâ vazgeçmeyi reddediyorsun? Neden hâlâ bu kadar inatçı bir karanlıkta, aydınlanmamış hâlde kalıyorsun?\n...Onları korumak için mi?\nEğer Senin Cevabın buysa, sonunda kemiklerini, kanını, bilincini—her şeyini teslim edeceksin."
  },
  Stage_58474_Name = {
    Text = "Kapının Ardındaki·Çılgınlık"
  },
  Stage_58474_StageInitStateText = {Text = "Köken"},
  Stage_58475_Desc = {
    Text = "Yalnız bir yıldız, koyu kıvamlı karanlıkta asılı duruyor.\nŞişiyor, tutuşuyor, sonsuz pamuk şekerine dönüşüyor.\nBirinin bir ömre sığan tüm sevgisi ve nefreti billurlaştı—söyle, sen hangi tadı alıyorsun?"
  },
  Stage_58475_Name = {
    Text = "Yıldızlar·Çılgınlık"
  },
  Stage_58476_Desc = {
    Text = "Lemuryalılar’ın öğrendiği ilk şey Dua idi. Yine de, onu korumak için karşısına çıkan kişi asla onun kralı olmadı."
  },
  Stage_58476_Name = {
    Text = "Ebedi Sorgu·Çılgınlık"
  },
  Stage_58476_StageInitStateText = {
    Text = "Deniz Kabusu"
  },
  Stage_58477_Desc = {
    Text = "Sayısız ruh hakikate susamış, dalgalar halinde ileri yürüyor. Sayısız budala, gerçeğin kırık parçalarına sarılıp kör aydınlanmaları ilahi ışık sanıyor, göksel ihtişamdan vaaz veriyor.\nYalnızca o, hakikatin şarabını buldu—ve lanetli nektarı tek yudumda içti.\nGulp.\nŞimdi zehirlenmiş halde yatıyor, içten içe çürüyerek. Sayısız ahmağın çoktan kanıtladığı üzere: hakikat, kadehteki zehirden ibaret.\nBir yudum azap getirir; bir içim, sonu. Zamanı tükeniyor… yine de sana ortak bir kadeh uzatıyor."
  },
  Stage_58477_Name = {
    Text = "Hakiki Zehir·Çılgınlık"
  },
  Stage_58478_Desc = {
    Text = "Alev alev havai fişekler gibi açıl, hayatın bizzat yakıt olsa bile.\nTüm menziller tek bir noktada birleşiyorken, neden sonsuz ıstıraba katlanıp durasın da, göz kamaştıran bir parıltıyı kucaklamayasın?"
  },
  Stage_58478_Name = {
    Text = "Parlak Çöküş·Çılgınlık"
  },
  Stage_58479_Desc = {
    Text = "Bu, Yedinci Kapı.\nBurada zamanın seli durulur ve ebedî bilgelik, kaybolmuş arayıcıyı en derin Şaşkınlıktan çıkarıp rehberlik eder."
  },
  Stage_58479_Name = {
    Text = "Son Sınırın Kapısı·Çılgınlık"
  },
  Stage_58479_StageInitStateText = {Text = "Köken"},
  Stage_58480_Desc = {
    Text = "Açılış—tema ilan edilir.\nBaşlangıcı ve sonu, soluk alışı ve verişi o Anlatacak."
  },
  Stage_58480_Name = {
    Text = "Uvertür·Çılgınlık"
  },
  Stage_58480_StageInitStateText = {Text = "Köken"},
  Stage_58691_Desc = {
    Text = "Rüzgâr diner, kar çekilir ve her şey filizlenir."
  },
  Stage_58691_Name = {Text = "Bir Bahar"},
  Stage_58692_Desc = {
    Text = "Yas tut ya da hayranlık duy. Bu, sıradağlara karşı açılmış bir savaşçının savaş ilanıdır."
  },
  Stage_58692_Name = {Text = "Dikenzirve"},
  Stage_58693_Desc = {
    Text = "Giysileri rüzgârda dalgalanıyor; şaşkınlığı hafifçe mırıldanıyor. Karşında duruyor."
  },
  Stage_58693_Name = {
    Text = "Yeniden Buluşma"
  },
  Stage_58694_Desc = {
    Text = "Düşmanı sen bulmadın. Düşman seni buldu."
  },
  Stage_58694_Name = {
    Text = "Karanlık Siluet"
  },
  Stage_58695_Desc = {
    Text = "Geri dön, çocuk. Dağ çağırıyor.\nAnnenin yumuşak çağrısına kulak ver ve kaderin huzurlu kucaklayışına geri dön."
  },
  Stage_58695_Name = {
    Text = "Dağların Çağrısı"
  },
  Stage_58696_Desc = {
    Text = "Hikâyeleri herkes için bilinmeyen yaratıklar gibi. İsimleri, yas tutulmadan yok olup gidiyor."
  },
  Stage_58696_Name = {Text = "Kurban"},
  Stage_58697_Desc = {
    Text = "Elworth, nazik ziyaretini pek hoş karşılamıyor."
  },
  Stage_58697_Name = {
    Text = "Kar Ovası Yabancısı"
  },
  Stage_58698_Desc = {
    Text = "Ay ışığının solgunluğu ile karın beyazlığı arasında, kan üçüncü ana renktir."
  },
  Stage_58698_Name = {
    Text = "Sonsuz Ayaz"
  },
  Stage_58699_Desc = {
    Text = "Hangisinin daha tehlikeli olduğunu söylemek zor."
  },
  Stage_58699_Name = {
    Text = "Dost ya da Düşman"
  },
  Stage_58700_Desc = {
    Text = "Yas tut ya da hayranlık duy. Bu, sıradağlara karşı açılmış bir savaşçının savaş ilanıdır."
  },
  Stage_58700_Name = {Text = "Dikenzirve"},
  Stage_58701_Desc = {
    Text = "Yas tut ya da hayranlık duy. Bu, sıradağlara karşı açılmış bir savaşçının savaş ilanıdır."
  },
  Stage_58701_Name = {Text = "Dikenzirve"},
  Stage_58976_Desc = {
    Text = "\"Bu yıkıma giden yolu metanetle adımlayışını izleyeceğim… Cenazende yas tutacağım.\""
  },
  Stage_58976_Name = {
    Text = "Sürdürüm Yolu"
  },
  Stage_58977_Desc = {
    Text = "\"Tiyatroda sayısız sahneyi severim. Ama en sevdiğim, en zarif porseleni tavan arasından aşağı fırlattıkları andır.\""
  },
  Stage_58977_Name = {
    Text = "Baba ve Kız"
  },
  Stage_58978_Desc = {
    Text = "Kaba, uzun, yanılsamalı. Herkesin yüzleşmesi gereken kendi yolu vardır.\nSonunda başlangıç noktasında durduğunda, önündeki ufka bakmaya yetecek cesaretin olacak mı?"
  },
  Stage_58978_Name = {Text = "Yol"},
  Stage_58979_Desc = {
    Text = "Ritim. Melodi. Tellerin yumuşak üst ezgileri zihnine sızıyor.\nSeyircinin sessiz bakışları arasında, Orkestra Şefi sahnesine yükseliyor."
  },
  Stage_58979_Name = {
    Text = "Orkestra Şefi"
  },
  Stage_58980_Desc = {
    Text = "Narin bedeni kaynayan toprağın içine gömülmüştü.\nO yanılsamalı boyutta Kara Havuz’la tek başına yüzleşti."
  },
  Stage_58980_Name = {
    Text = "Kalıntılar"
  },
  Stage_58981_Desc = {
    Text = "Yanlış bir nota, kaçırılmış bir giriş… en ufak bir tökezleme tüm performansı mahvedebilir.\nÇalış. Sonsuz bir prova döngüsünde alkışını bekle."
  },
  Stage_58981_Name = {Text = "Prova"},
  Stage_58982_Desc = {
    Text = "Unutuş, dünyanın nihai Arındırma’sı mıdır? Mythag buna asla katılmaz.\nBu kampüsteki insanlar, hatırlamak için savaşacak."
  },
  Stage_58982_Name = {Text = "Lex Lethis"},
  Stage_58982_StageInitStateText = {Text = "Son Perde"},
  Stage_58983_Desc = {
    Text = "Neşeli dans ezgileri, keyifli şakalaşmalar ve donuk, tekdüze bir iş.\nEvet, Üçüncü Bölüm sırasında dinlen. Güvenli, sakin ve olaysızdır."
  },
  Stage_58983_Name = {
    Text = "Üçüncü Bölüm"
  },
  Stage_58984_Desc = {
    Text = "Yalvarmanın yolu yok. Kaçmanın yolu yok. Bu, bu dünyanın yazgısı.\nOnları yen. Onları öldür. Ve sonra, onları kurtar."
  },
  Stage_58984_Name = {Text = "Kader"},
  Stage_58985_Desc = {
    Text = "Önceden haber verilmiş bir bükülme gücünü yitirir, ama o hiç umursamaz.\nOnun beklediği haz bambaşka bir yerde yatar."
  },
  Stage_58985_Name = {
    Text = "Dexter Tarzı Dönüş"
  },
  Stage_58986_Desc = {
    Text = "Şşş.\nSon seyirci de yerine oturdu. Gerçek temsil başlamak üzere."
  },
  Stage_58986_Name = {Text = "Giriş"},
  Stage_58987_Desc = {
    Text = "Bilgi asimetrikken, ne kadar kusursuz görünürse, yanılgısı o kadar ağır olur."
  },
  Stage_58987_Name = {
    Text = "İyi Öğrenci, Kötü Öğrenci"
  },
  Stage_58988_Desc = {
    Text = "\"Mythag, hem Leo Krallığı’nın hem de Mystia Antlaşma Denetim Komitesi’nin yargı yetkisinden bağımsızdır. Her türlü izinsiz giriş, yasa dışı ihlal sayılacak ve Mythag, meşru müdafaa hakkını bütünüyle saklı tutacaktır.\""
  },
  Stage_58988_Name = {
    Text = "Okul Kuralları"
  },
  Stage_59049_Desc = {
    Text = "Ritim. Melodi. Tellerin yumuşak üst ezgileri zihnine sızıyor.\nSeyircinin sessiz bakışları arasında, Orkestra Şefi sahnesine yükseliyor."
  },
  Stage_59049_Name = {
    Text = "Orkestra Şefi"
  },
  Stage_59050_Desc = {
    Text = "Yanlış bir nota, kaçırılmış bir giriş… en ufak bir tökezleme tüm performansı mahvedebilir.\nÇalış. Sonsuz bir prova döngüsünde alkışını bekle."
  },
  Stage_59050_Name = {Text = "Prova"},
  Stage_59051_Desc = {
    Text = "\"Mythag, hem Leo Krallığı’nın hem de Mystia Antlaşma Denetim Komitesi’nin yargı yetkisinden bağımsızdır. Her türlü izinsiz giriş, yasa dışı ihlal sayılacak ve Mythag, meşru müdafaa hakkını bütünüyle saklı tutacaktır.\""
  },
  Stage_59051_Name = {
    Text = "Okul Kuralları"
  },
  Stage_59052_Desc = {
    Text = "\"Bu yıkıma giden yolu metanetle adımlayışını izleyeceğim… Cenazende yas tutacağım.\""
  },
  Stage_59052_Name = {
    Text = "Sürdürüm Yolu"
  },
  Stage_59053_Desc = {
    Text = "Önceden haber verilmiş bir bükülme gücünü yitirir, ama o hiç umursamaz.\nOnun beklediği haz bambaşka bir yerde yatar."
  },
  Stage_59053_Name = {
    Text = "Dexter Tarzı Dönüş"
  },
  Stage_59054_Desc = {
    Text = "Narin bedeni kaynayan toprağın içine gömülmüştü.\nO yanılsamalı boyutta Kara Havuz’la tek başına yüzleşti."
  },
  Stage_59054_Name = {
    Text = "Kalıntılar"
  },
  Stage_59055_Desc = {
    Text = "Kaba, uzun, yanılsamalı. Herkesin yüzleşmesi gereken kendi yolu vardır.\nSonunda başlangıç noktasında durduğunda, önündeki ufka bakmaya yetecek cesaretin olacak mı?"
  },
  Stage_59055_Name = {Text = "Yol"},
  Stage_59056_Desc = {
    Text = "Yalvarmanın yolu yok. Kaçmanın yolu yok. Bu, bu dünyanın yazgısı.\nOnları yen. Onları öldür. Ve sonra, onları kurtar."
  },
  Stage_59056_Name = {Text = "Kader"},
  Stage_59057_Desc = {
    Text = "Neşeli dans ezgileri, keyifli şakalaşmalar ve donuk, tekdüze bir iş.\nEvet, Üçüncü Bölüm sırasında dinlen. Güvenli, sakin ve olaysızdır."
  },
  Stage_59057_Name = {
    Text = "Üçüncü Bölüm"
  },
  Stage_59058_Desc = {
    Text = "Kara su kudurmuşçasına kabarır, ilk ve tek efendilerini karşılar."
  },
  Stage_59058_Name = {
    Text = "Kara Havuzun Gelgitleri I"
  },
