  Stage_59502_Desc = {
    Text = "İlksel umutsuzluğunla yüzleş. İlksel korkunla yüzleş.\nBirbirinizin yanında, görünmeden durun ve sonra O'nu alt edin."
  },
  Stage_59502_Name = {
    Text = "Belirleyici: İlksel Gölge"
  },
  Stage_59503_Desc = {
    Text = "Hatırlamak senin yeminindir; unutmak ise senin ritüelin."
  },
  Stage_59503_Name = {Text = "Ayîn"},
  Stage_59503_StageInitStateText = {Text = "Köken"},
  Stage_59504_Desc = {
    Text = "Rüya Tapınak’ında duruyor, çöken harabeleri ayakta tutuyorsun.\nAltındaki toz zerresini koruyorsun—tüm Adanmışlık ve özlemini taşıyan o zerreyi."
  },
  Stage_59504_Name = {
    Text = "Rüyanın Çöküşü"
  },
  Stage_59504_StageInitStateText = {Text = "Köken"},
  Stage_59505_Desc = {
    Text = "\"Hayatta kalmak mı, yok olmak mı?\""
  },
  Stage_59505_Name = {Text = "Rehber"},
  Stage_59505_StageInitStateText = {Text = "Köken"},
  Stage_59506_Desc = {
    Text = "Hatırlamak senin yeminindir; unutmak ise senin ritüelin."
  },
