  Stage_62348_Desc = {
    Text = "Bu, Yıldızlar’ın Yükselen Ezgi’si. Bu, kozmosun Son Perde’si.\nBu derin Sessizlik’te dikkatle dinle—\ngerçek notaları duyabiliyor musun?"
  },
  Stage_62348_Name = {Text = "Son Perde"},
  Stage_66016_Desc = {
    Text = "O, Yüce İrade'dir; evrenin Yaratıcısı ve her şeyin Sonlandırıcısıdır.\nÖnünde feryat et. Çelimsiz cesaretin için, O'nun hudutsuz Yetkileri için."
  },
  Stage_66016_Name = {
    Text = "Yoksullar Evi: Ağıtın Vizyonu"
  },
  Stage_66016_StageInitStateText = {Text = "Köken"},
  Stage_66017_Desc = {
    Text = "O, Yüce İrade'dir; evrenin Yaratıcısı ve her şeyin Sonlandırıcısıdır.\nÖnünde feryat et. Çelimsiz cesaretin için, O'nun hudutsuz Yetkileri için."
  },
  Stage_66017_Name = {
    Text = "Yoksullar Evi: Ağıtın Vizyonu"
  },
  Stage_66017_StageInitStateText = {Text = "Köken"},
  Stage_66018_Desc = {
    Text = "O, Yüce İrade'dir; evrenin Yaratıcısı ve her şeyin Sonlandırıcısıdır.\nÖnünde feryat et. Çelimsiz cesaretin için, O'nun hudutsuz Yetkileri için."
  },
  Stage_66018_Name = {
    Text = "Yoksullar Evi: Ağıtın Vizyonu"
  },
  Stage_66381_Desc = {
    Text = "Kaygılanma; zira korku, canlı varlıkların en ilkel içgüdüsüdür.\nİlahi olan, tek bir karıncayı bile rahatsız etmez. O, seni Uyanış nimetiyle kutsar."
  },
  Stage_66381_Name = {
    Text = "Balmumu Müzesi:: Korku Görüşü"
  },
  Stage_66381_StageInitStateText = {Text = "Köken"},
  Stage_66382_Desc = {
    Text = "Söyle, söyle büyük Yaratıcımızı!\nO rüya gördüğünde, diriler serpilir.\nO gözlerini açtığında, her şey toza döner."
  },
  Stage_66382_Name = {
    Text = "Bridgeport: Sapkınlık Vizyonu"
  },
  Stage_66382_StageInitStateText = {Text = "Köken"},
  Stage_66383_Desc = {
    Text = "Acıyı hisset; Yüce İradenin en ilkel armağanını hisset.\nAcı aracılığıyla, Yaratıcı’nın azametini bir anlığına görebilirsin."
  },
  Stage_66383_Name = {
    Text = "Çavdar: Ürperti Vizyonu"
  },
  Stage_66383_StageInitStateText = {Text = "Köken"},
  Stage_66384_Desc = {
    Text = "Çırpınmana gerek yok. Direnmene gerek yok. Neden kavranamaz olanı kavramaya çalışıyorsun?\nYüce İradenin Nazarı altında, gel, düşün sonunu kucaklayalım."
  },
  Stage_66384_Name = {
    Text = "Sanatoryum: Muamma Vizyonu"
  },
  Stage_66384_StageInitStateText = {Text = "Köken"},
  Stage_66385_Desc = {
    Text = "O, Yüce İrade'dir; evrenin Yaratıcısı ve her şeyin Sonlandırıcısıdır.\nÖnünde feryat et. Çelimsiz cesaretin için, O'nun hudutsuz Yetkileri için."
  },
  Stage_66385_Name = {
    Text = "Yoksullar Evi: Ağıtın Vizyonu"
  },
  Stage_66385_StageInitStateText = {Text = "Köken"},
  Stage_67123_Desc = {
    Text = "O görkemli uygarlık, insan dünyasının o sevinçleri ve ağıtları, etrafında gelip geçen sayısız insan—hiç var olmadı. Düşlerin Çözünmesi eninde sonunda gelecek.\nUnut, Koruyucu. Unutuş, acıların en görkemlisidir.\nUnutuş, yüce saadetin ilacıdır."
  },
  Stage_67123_Name = {
    Text = "Remouahe: Doğuşun Görüş Alanı"
  },
  Stage_67123_StageInitStateText = {Text = "Köken"},
  Stage_67124_Desc = {
    Text = "Körce taşan ahmaklık selinin üzerinde, düzenin kulesi çöker.\nAklın hiç var olmadı; yalnızca Delilik senin yazgındır."
  },
