  Stage_70102_Desc = {
    Text = "Fidanlar, pervasız maceracılardır.\nTohumlar, bir sonraki karış Toprak’ın verimli kara toprak mı yoksa soğuk, kısır kum mu olduğunu bilmezler—korkusuz bir kararlılıkla köklerini derine salarlar."
  },
  Stage_70102_Name = {
