  },
  Stage_72072_Name = {
    Text = "Dünyevi Rızık"
  },
  Stage_74229_Desc = {
    Text = "O dalgalanan etekle tesadüfen karşılaşırsın—uçan bir kuğunun kanatlarına benzeyen, ama aynı zamanda bir alevi andıran dönen etekle."
  },
  Stage_74229_Name = {
    Text = "Beklenmedik Alevler"
  },
  Stage_74230_Desc = {
    Text = "Burası bir sanat tapınağı değil mi? Aksi hâlde bunca göz kamaştırıcı, zarif hareket nasıl açıklanır?\nAma gerçekten bir sanat tapınağı mı? Öyleyse bunca soğuk, yağlı bakış nasıl açıklanır?"
  },
  Stage_74230_Name = {Text = "Yanan Buz"},
  Stage_74231_Desc = {
    Text = "Rüyadaki kuğu göğe yükselir, sonra avcının ağına çakılır."
  },
  Stage_74231_Name = {
    Text = "Bir Yaz Gecesi Rüyası"
  },
  Stage_74232_Desc = {
