  Stage_75762_Name = {
    Text = "Bataklık Dehşeti·Bölüm II"
  },
  Stage_75763_Desc = {
    Text = "Kendi adını çoktan unutmuştu, onunla ilk tanıştığı günün Hafızası bile bulanıklaşmaya başlamıştı.\nYalnızca o eller, onu usulca kavrayan o eller, vahşi ve yalnız ruhunu hep ısıtmıştı.\nBu yüzden, güzel başı onun ellerinden aldı, isteyerek ebedî maskeyi ve Zincirler'i kuşandı."
  },
  Stage_75763_Name = {
    Text = "O ve O·Bölüm VI"
  },
  Stage_75764_Desc = {
    Text = "Cesetler, kan kokusu, iz bırakmadan yok olmuş bir baş.\nSeni koruyacak mı—yoksa senin canını da mı alacak?"
