  Stage_7647_Name = {
    Text = "Hayali Dalış I"
  },
  Stage_7648_Desc = {
    Text = "İhlalcileri durmaksızın kovalar.\n \"Kurallar\"ı neyin oluşturduğu ve neyin onları \"çiğnemek\" sayıldığına gelince?\nTazı asla düşünmez—düşünmek kovalamacayı yalnızca yavaşlatır."
  },
  Stage_7648_Name = {
    Text = "Diyar Ötesi Gölge III"
  },
  Stage_7649_Desc = {
    Text = "Londinium, göz kamaştırıcı endüstriyel uygarlığı ve şehri saran kurşuni sisiyle Ünlü’dür.\nSis her yerdedir—yoldan geçenler için, önemsiz, anlamsız bir rahatsızlıktan fazlası değildir."
  },
  Stage_7649_Name = {
    Text = "Büyük Duman Şehri II"
  },
  Stage_7650_Desc = {
    Text = "Bilinmeyen kökenli putlar karanlıkta dolaşır, titrer.\nUzak bir flütün sesine kapılıp, kadim ritimlere göre hareket ederler."
  },
  Stage_7650_Name = {
    Text = "Caro Bataklığı: Çatlak VII"
  },
  Stage_7651_Desc = {
    Text = "Kaba, sindirilmemiş bir yığın. İnsanlar ona dışkı—ya da kaos—der.\nDünya, dışkıdan doğdu."
  },
  Stage_7651_Name = {
    Text = "Kaos Kümesi V"
  },
  Stage_7652_Desc = {
    Text = "Kıvranarak, sızarak... O protoplazmik kütle, Zincirler’inin çatlaklarından süzülür.\nBu, onun \"özgürlük\" için ödediği bedeldir."
  },
  Stage_7652_Name = {
    Text = "Karanlık Zinciri III"
  },
  Stage_7653_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7653_Name = {
    Text = "Ultra Yolculuğu: Dönüşüm Aralığı I"
  },
  Stage_7654_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7654_Name = {
    Text = "Ultra Yolculuğu: Dönüşüm Aralığı I"
  },
  Stage_7655_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7655_Name = {
    Text = "Ultra Yolculuğu: Dönüşüm Aralığı I"
  },
  Stage_7656_Desc = {
    Text = "Uysal bir dinlenme ve toparlanma hâlinde, yatağın kenarına yaslanmıştır; donuk düğme gözleri boşluğa dikilidir.\nKüçük beden, sahibinin tüm gözyaşlarını taşımıştır, ama tek bir teselli sözü sunamaz."
  },
  Stage_7656_Name = {
    Text = "Kuklanın Gözyaşları V"
  },
  Stage_7657_Desc = {
    Text = "Onlar, ağıt, Bükülme ve saflığın bilinçsiz bir bileşimiydi;\nneşeli Çocuklar, yetişkinler ve evcil hayvanlar kılığına bürünmüşlerdi.\nHiç mutluluk tatmadıkları için, hepsi en kötü oyunculara dönüştü."
  },
  Stage_7657_Name = {
    Text = "Heykelin Sırları V"
  },
  Stage_7658_Desc = {
    Text = "\"Kapı\" açıldı. Düş sona yaklaşmakta.\nSus... Bakma. Dinleme."
  },
  Stage_7658_Name = {
    Text = "Kaos Diyarı: Çatlak IV"
  },
  Stage_7659_Desc = {
    Text = "Fırtına hâlâ kaynıyor. Henüz bitmedi."
  },
  Stage_7659_Name = {
    Text = "Gerçeklik Yeniden Başlatma"
  },
  Stage_7660_Desc = {
    Text = "Ne görkemli bir manzara, ne de büyüleyici bir kahraman kadın.\n—Yalnızca üç adamın sahnelediği sıkıcı bir oyun."
  },
  Stage_7660_Name = {
    Text = "Rehber, Büyücü ve Köle"
  },
  Stage_7661_Desc = {
    Text = "Rüzgâra ve kumlara karşı, savaşçı tereddütsüz güneşe doğru şarj eder."
  },
  Stage_7661_Name = {
    Text = "Güneş Seferi"
  },
  Stage_7662_Desc = {
    Text = "Dostlar, bırakın kavgalarınızı ve çekişmelerinizi.\nKurban alevleri yükseldi. Ölümden önceki bu son huzurun tadını çıkarın."
  },
  Stage_7662_Name = {
    Text = "Kızıl Ayin"
  },
  Stage_7663_Desc = {
    Text = "Teknik olarak, bu bir trajedi değildir.\n\"Trajedi\" sözcüğünün bir savaşçının sözlüğünde yeri yoktur."
  },
  Stage_7663_Name = {
    Text = "Trajedinin Perdesi"
  },
  Stage_7664_Desc = {
    Text = "Karaya doğru yelken aç—bir umut parıltısına doğru."
  },
  Stage_7664_Name = {
    Text = "Trajik Yola Çıkış"
  },
  Stage_7665_Desc = {
    Text = "Kozmosun derinliklerinde gizlenen eğri ufuk.\nSeni bir karanlıktan alıp diğerine götürür."
  },
  Stage_7665_Name = {
    Text = "Schwarzschild Boğazı III"
  },
  Stage_7666_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7666_Name = {
    Text = "Aequor Mirası: Çatlak III"
  },
  Stage_7667_Desc = {
    Text = "\"O Bir’dir. O Tüm’dür. O, Hakikat’in kapısını açan umuttur.\"\nSayısız anahtar bir çember oluşturdu. Gökyüzünden düşerek, insanlığa ağır bir umut getirdiler.\nVe ağır mezarlar."
  },
