  Stage_7673_Name = {
    Text = "Hayali Dalış I"
  },
  Stage_7674_Desc = {
    Text = "Dökülen put, halkına bakar;\nOnların hayatta kalışını, çoğalışını, savaşını—andan sonra da onu tümden unutmalarını seyreder.\nDökülen put, halkını özler..."
  },
  Stage_7674_Name = {
    Text = "Hayali Dalış III"
  },
  Stage_7675_Desc = {
    Text = "Kuzey Yorkshire’da bir sahil kasabası—Scarborough. Yükselen kayalıkları ve altın rengi koylarıyla zarif ve büyüleyici bir tatil beldesi."
  },
  Stage_7675_Name = {
    Text = "Scarborough Yazı"
  },
  Stage_7676_Desc = {
