  },
  Stage_7676_Name = {
    Text = "Hayali Dalış I"
  },
  Stage_7677_Desc = {
    Text = "Bir küçük fare, bir küçük fare.\nKoş, koş! Onun kuyruğunu satırla kesti."
  },
  Stage_7677_Name = {
    Text = "Brown'un Hücumu"
  },
  Stage_7678_Desc = {
