  Stage_77103_Name = {
    Text = "D-Etkisi Yasak Bölgesi: Dalga 5: Seviye III Alarm"
  },
  Stage_7710_Desc = {
    Text = "Günlükler, Hafıza’nın parçalarıdır.\nGünlükler daima Soruşturmalar sırasında keşfedilir."
  },
  Stage_7710_Name = {
    Text = "Hafıza Parçaları"
  },
  Stage_7711_Desc = {
    Text = "Onun için yaratılmış bir diyar—derin bir aşk ve dehşet verici bir kafes, ikisi de aynı şey."
  },
  Stage_7711_Name = {Text = "Tımarhane"},
  Stage_7712_Desc = {
    Text = "Soylular güçlerini, zenginler servetlerini yitirdiğinde, çaresiz kalırlar—tıpkı şu anda senin gibi."
  },
  Stage_7712_Name = {
    Text = "Guguk Kuşu Sığınağı"
  },
  Stage_7713_Desc = {
    Text = "Çatışma, yalnızca savaş alanına hapsedilemez. Bazen delilerin hezeyanlarında ikamet eder."
  },
  Stage_7713_Name = {
    Text = "Delinin Ağzı"
  },
  Stage_7714_Desc = {
    Text = "Siste sarmalanmış izler, üzerlerinde dolaşan sayısız ayak sesleri—her adım, kadere yöneltilmiş bir soru."
  },
  Stage_7714_Name = {Text = "Sapan Yol"},
  Stage_7715_Desc = {
    Text = "Sessiz alev, yanından geçenlere içi boş vaatler fısıldar."
  },
  Stage_7715_Name = {
    Text = "Güve Kapanı Ateşi"
  },
  Stage_7716_Desc = {
    Text = "Et ve kandan dövülmüş gerçeği sun—onlar doyumsuz bir uçurumdur."
  },
  Stage_7716_Name = {
    Text = "Organik Kalıntı V"
  },
  Stage_7717_Desc = {
    Text = "Fırtına hâlâ kaynıyor. Henüz bitmedi."
  },
  Stage_7717_Name = {
    Text = "Gerçeklik Yeniden Başlatma"
  },
  Stage_7718_Desc = {
    Text = "Karaya doğru yelken aç—bir umut parıltısına doğru."
  },
  Stage_7718_Name = {
    Text = "Trajik Yola Çıkış"
  },
  Stage_7719_Desc = {
    Text = "O, asla arzu edilmiş bir varlık değildi; yalnızca pis bir parazitti."
  },
  Stage_7719_Name = {Text = "Parazit"},
  Stage_7720_Desc = {
    Text = "Gecenin sonsuz Karanlığında, baştan çıkarıcı ışığın peşine düşmek; alevlere çekilen bir güve gibi, yazgının alevlerine, geride hiçbir şey bırakmadan kanat çırpmak."
  },
  Stage_7720_Name = {
    Text = "Alevi Kovalayan Güve"
  },
  Stage_7721_Desc = {
    Text = "Gece, Akıntılar tarafından kemiriliyor ve yıldızlar susuyor. Kıvrımlarla ve fırtınalarla yüklü Kriz Ayı, sessizce bilinmeyen bir geleceği yansıtıyor."
  },
  Stage_7721_Name = {Text = "Kriz Ayı"},
  Stage_7722_Desc = {
    Text = "Kaderin fırtınalı rüzgârlarında titreyip çırpınabilirsin, ama asla gerçekten savrulup kaybolmayacaksın."
  },
  Stage_7722_Name = {
    Text = "Uçurum Kenarı"
  },
  Stage_7723_Desc = {
    Text = "Yılların geçidi boyunca tahammül eden dostluklar, yeni bir umut filizlendirdi."
  },
  Stage_7723_Name = {
    Text = "Eski Dostlar, Yeni Bağlar"
  },
  Stage_7724_Desc = {
    Text = "Onun hükümranlığı, kozmosun kabuğudur ve arzuları sınır tanımaz."
  },
  Stage_7724_Name = {
    Text = "Solucan Yuvası III"
  },
  Stage_7725_Desc = {
    Text = "Et ve kandan dövülmüş gerçeği sun—onlar doyumsuz bir uçurumdur."
  },
  Stage_7725_Name = {
    Text = "Organik Kalıntı II"
  },
  Stage_7726_Desc = {
    Text = "Onlar, ağıt, Bükülme ve saflığın bilinçsiz bir bileşimiydi;\nneşeli Çocuklar, yetişkinler ve evcil hayvanlar kılığına bürünmüşlerdi.\nHiç mutluluk tatmadıkları için, hepsi en kötü oyunculara dönüştü."
  },
  Stage_7726_Name = {
    Text = "Heykelin Sırları I"
  },
  Stage_7727_Desc = {
    Text = "Uysal bir dinlenme ve toparlanma hâlinde, yatağın kenarına yaslanmıştır; donuk düğme gözleri boşluğa dikilidir.\nKüçük beden, sahibinin tüm gözyaşlarını taşımıştır, ama tek bir teselli sözü sunamaz."
  },
  Stage_7727_Name = {
    Text = "Kuklanın Gözyaşları I"
  },
  Stage_7728_Desc = {
    Text = "\"O Bir’dir. O Tüm’dür. O, Hakikat’in kapısını açan umuttur.\"\nSayısız anahtar bir çember oluşturdu. Gökyüzünden düşerek, insanlığa ağır bir umut getirdiler.\nVe ağır mezarlar."
  },
