    Text = "Dökülen put, halkına bakar;\nOnların hayatta kalışını, çoğalışını, savaşını—andan sonra da onu tümden unutmalarını seyreder.\nDökülen put, halkını özler..."
  },
  Stage_7742_Name = {
    Text = "Hayali Dalış I"
  },
  Stage_7743_Desc = {
    Text = "Onlar, Yıldızlar doğmadan çok önce var oldular.\nOnlar hem Düş hem de her şeydir."
  },
  Stage_7743_Name = {
    Text = "Bulanık Kalıntı I"
  },
  Stage_7744_Desc = {
    Text = "Onlar karanlıkta bükülüp birleşir, sonra putların içinde itinayla saklanır.\nBu, önceden tasarlanmış bir kavuşmadır."
  },
  Stage_7744_Name = {
    Text = "Aequor Mirası: Çatlak I"
  },
  Stage_7745_Desc = {
    Text = "Kutsal kalıntıyı kendi etinde taşır, mümini doktrinle güder ve inancı zehirli dişleriyle yayar."
  },
  Stage_7745_Name = {
    Text = "Dindarlık Kavrayışı I"
  },
  Stage_7746_Desc = {
    Text = "\"Kapı\" açıldı. Düş sona yaklaşmakta.\nSus... Bakma. Dinleme."
  },
  Stage_7746_Name = {
    Text = "Aequor Mirası: Çatlak IV"
  },
  Stage_7747_Desc = {
    Text = "Rye Kasabası, Londinium’un kuzeydoğusunda, uzayıp giden dağ sıralarının arasında Gizlenme hâlindedir.\nSessiz Kasabalılar, her an tetikte gözler... Sakın ha, burada hiçbir şey göründüğü gibi değildir."
  },
  Stage_7747_Name = {
    Text = "Çılgınlık Kasabası I"
  },
  Stage_7748_Desc = {
    Text = "Ah, lağımlar—kentin vicdanı, kentin akıl hastanesi."
  },
  Stage_7748_Name = {Text = "Alt Kanal"},
  Stage_7749_Desc = {
    Text = "Elbette, elbette. Gözler zihnin zindanı; ruh ise bedenin prangasıdır."
  },
  Stage_7749_Name = {
    Text = "Anatominin Melankolisi"
  },
  Stage_7750_Desc = {
    Text = "Boşluk bizim kökenimiz. Boşluk bizim sonumuz."
  },
  Stage_7750_Name = {
    Text = "Ölümsüzün Fısıltıları"
  },
  Stage_7751_Desc = {
    Text = "Aynen öyle, bebeğim. İstediğin kadar ağla ve acını bir başyapıt gibi çerçevele."
  },
  Stage_7751_Name = {
    Text = "Kız ve Gözyaşları"
  },
  Stage_7752_Desc = {
    Text = "İhlalcileri durmaksızın kovalar.\n \"Kurallar\"ı neyin oluşturduğu ve neyin onları \"çiğnemek\" sayıldığına gelince?\nTazı asla düşünmez—düşünmek kovalamacayı yalnızca yavaşlatır."
  },
  Stage_7752_Name = {
    Text = "Diyar Ötesi Gölge II"
  },
  Stage_7753_Desc = {
    Text = "Gerçeklik—acımasız, amansız gerçeklik."
  },
  Stage_7753_Name = {
    Text = "Peçenin Ardında"
  },
  Stage_7754_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7754_Name = {
    Text = "Caro Bataklığı: Dönüşüm Aralığı II"
  },
  Stage_7755_Desc = {
    Text = "Savaşçı daha sonra evine döndü, prensesle evlendi ve mutlu, huzurlu bir hayat sürdü.\nÖyle mi? Hayır, hiç de öyle değil."
  },
  Stage_7755_Name = {Text = "Son Söz"},
  Stage_7756_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7756_Name = {
    Text = "Caro Bataklığı: Dönüşüm Aralığı I"
  },
  Stage_7757_Desc = {
