  Stage_7758_Name = {
    Text = "Caro Bataklığı: Dönüşüm Aralığı I"
  },
  Stage_7759_Desc = {
    Text = "Yağmur indiğinde ve kan dalgalandığında, kavuşma anı gelir.\nUzun zaman oldu, Koruyucu."
  },
  Stage_7759_Name = {
    Text = "Tesadüfi Kesişme"
  },
  Stage_7760_Desc = {
    Text = "Issız demiryolu köprüsünün altında, devasa, şişkin bir Canavar tuhaf hırıltılar salar. Rye Sanatoryumu’na ulaşmak için önce buradan geçmelisin."
  },
  Stage_7760_Name = {
    Text = "Akıntı Seni Yönlendirecek"
  },
  Stage_7761_Desc = {
    Text = "Dahi Farmakolog olmaya atılan ilk adım."
