    Text = "\"O Bir’dir. O Tüm’dür. O, Hakikat’in kapısını açan umuttur.\"\nSayısız anahtar bir çember oluşturdu. Gökyüzünden düşerek, insanlığa ağır bir umut getirdiler.\nVe ağır mezarlar."
  },
  Stage_7809_Name = {
    Text = "Hayali Dalış II"
  },
  Stage_7810_Desc = {
    Text = "\"O Bir’dir. O Tüm’dür. O, Hakikat’in kapısını açan umuttur.\"\nSayısız anahtar bir çember oluşturdu. Gökyüzünden düşerek, insanlığa ağır bir umut getirdiler.\nVe ağır mezarlar."
  },
  Stage_7810_Name = {
    Text = "Hayali Dalış V"
  },
  Stage_7811_Desc = {
    Text = "\"O Bir’dir. O Tüm’dür. O, Hakikat’in kapısını açan umuttur.\"\nSayısız anahtar bir çember oluşturdu. Gökyüzünden düşerek, insanlığa ağır bir umut getirdiler.\nVe ağır mezarlar."
  },
  Stage_7811_Name = {
    Text = "Hayali Dalış IV"
  },
  Stage_7812_Desc = {
    Text = "\"O Bir’dir. O Tüm’dür. O, Hakikat’in kapısını açan umuttur.\"\nSayısız anahtar bir çember oluşturdu. Gökyüzünden düşerek, insanlığa ağır bir umut getirdiler.\nVe ağır mezarlar."
  },
  Stage_7812_Name = {
    Text = "Hayali Dalış VII"
  },
  Stage_7813_Desc = {
    Text = "\"O Bir’dir. O Tüm’dür. O, Hakikat’in kapısını açan umuttur.\"\nSayısız anahtar bir çember oluşturdu. Gökyüzünden düşerek, insanlığa ağır bir umut getirdiler.\nVe ağır mezarlar."
  },
  Stage_7813_Name = {
    Text = "Hayali Dalış VI"
  },
  Stage_7814_Desc = {
    Text = "Bu, okyanusu yarıp ikiye bölmek isteyenin devasa kılıcıydı; tüm denizleri boyunduruk altına almak isteyenin hırsıydı."
  },
  Stage_7814_Name = {
    Text = "Delinin Satırı"
  },
  Stage_7815_Desc = {
    Text = "Gerçeklik yıkımın tohumlarını ekerken, kader karşılaşmayı yönlendirir."
  },
  Stage_7815_Name = {
    Text = "Kaderin Tohumu"
  },
  Stage_7816_Desc = {
    Text = "Denizin Havarisi."
  },
  Stage_7816_Name = {Text = "Havari"},
  Stage_7817_Desc = {
    Text = "Bir gemide, Kaptan'dan başka kime güvenilebilir?"
  },
  Stage_7817_Name = {
    Text = "Mürettebat Üyesi"
  },
  Stage_7818_Desc = {
    Text = "Çıkış yolu kalmadığında, iyi eğitilmiş bir yoldaş çoğu zaman Kırılma’nın anahtarıdır—Ramona sana bu dersi bir kez daha verdi."
  },
  Stage_7818_Name = {
    Text = "Kaçış Yok"
  },
  Stage_7819_Desc = {
    Text = "Nice denizleri aşarken—düşmanların yanı sıra, belki bir parıltı kadar umut da vardır."
  },
  Stage_7819_Name = {Text = "Müptela"},
  Stage_7820_Desc = {
    Text = "Gece vakti liman, sade Sakinler ve onların sıcak misafirperverliği."
  },
  Stage_7820_Name = {
    Text = "Dört Bir Yandan Pusu"
  },
  Stage_7821_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7821_Name = {
    Text = "Aequor Mirası: Dönüşüm Aralığı II"
  },
  Stage_7822_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7822_Name = {
    Text = "Aequor Mirası: Dönüşüm Aralığı II"
  },
  Stage_7823_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7823_Name = {
    Text = "Aequor Mirası: Dönüşüm Aralığı II"
  },
  Stage_7824_Desc = {
    Text = "Murphy’nin içinde ikinci bir kalp atıyor—yaklaşan \"Doğum Ritüeli\" ni engellemeliyiz."
  },
  Stage_7824_Name = {
    Text = "Bir Başka Mucize"
  },
  Stage_7825_Desc = {
    Text = "Yarıp geçmek asla kolay değildir. Ama bu kez, Koruyucu gökkubbedeki en parlak yıldızı buldu."
  },
  Stage_7825_Name = {
    Text = "Yıldızların Peşinde"
  },
  Stage_7826_Desc = {
    Text = "Rogers Balmumu Müzesi, Southwark Caddesi’nin en ucunda, Taym’in bir koluna yakın bir yerde durur.\nGörünüşte gösterişsizdir, ama Uzaklardan Avangard Sanat meraklılarını kendine çeker."
  },
  Stage_7826_Name = {
    Text = "Çılgın Balmumu Müzesi I"
  },
  Stage_7827_Desc = {
    Text = "O, O olamaz, ve O asla o olamaz.\nEvet... Evet, yalnızca benim Tanrım gerçek O’dur."
  },
  Stage_7827_Name = {
    Text = "Yitik Işık"
  },
  Stage_7830_Desc = {
    Text = "Burada, tüm gücü tükenmiş, paramparça ve yaralı bir üniversite gömülüdür\nBir zamanlar, insanlığın hayatta kalışı için cılız bir Parıltı sunacak kadar yürekliydi\nKaderine gelince—onu şimdi gözlerinin önünde görüyorsun."
  },
  Stage_7830_Name = {
    Text = "Hayali Dalış V"
  },
  Stage_7831_Desc = {
    Text = "Burada, tüm gücü tükenmiş, paramparça ve yaralı bir üniversite gömülüdür\nBir zamanlar, insanlığın hayatta kalışı için cılız bir Parıltı sunacak kadar yürekliydi\nKaderine gelince—onu şimdi gözlerinin önünde görüyorsun."
  },
  Stage_7831_Name = {
    Text = "Hayali Dalış II"
  },
  Stage_7832_Desc = {
    Text = "Burada, tüm gücü tükenmiş, paramparça ve yaralı bir üniversite gömülüdür\nBir zamanlar, insanlığın hayatta kalışı için cılız bir Parıltı sunacak kadar yürekliydi\nKaderine gelince—onu şimdi gözlerinin önünde görüyorsun."
  },
  Stage_7832_Name = {
    Text = "Hayali Dalış III"
  },
  Stage_7833_Desc = {
    Text = "Burada, tüm gücü tükenmiş, paramparça ve yaralı bir üniversite gömülüdür\nBir zamanlar, insanlığın hayatta kalışı için cılız bir Parıltı sunacak kadar yürekliydi\nKaderine gelince—onu şimdi gözlerinin önünde görüyorsun."
  },
  Stage_7833_Name = {
    Text = "Hayali Dalış I"
  },
  Stage_7834_Desc = {
    Text = "Burayı kasıp kavuran hastalık, sıradan bir illet değil."
  },
  Stage_7834_Name = {Text = "Maraz"},
  Stage_7835_Desc = {
    Text = "Bisturiler, kayboluşlar ve ölüm, Yoksullar Evi'ni saran yoğun sisin\niçinde dolaşanları bekliyor."
  },
  Stage_7835_Name = {
    Text = "Kızılgerdan'ı Kim Öldürdü"
  },
  Stage_7836_Desc = {
    Text = "Onun hükümranlığı, kozmosun kabuğudur ve arzuları sınır tanımaz."
  },
  Stage_7836_Name = {
    Text = "Solucan Yuvası V"
  },
  Stage_7837_Desc = {
    Text = "Sen ve Ramona, yeni bir Koruyucu olarak ilk soruşturman için\nLondinium'un doğu bölgesinde bulunan Lilian'ın Çalışma Atölyesi'ne gidiyorsunuz.\nHer şey sorunsuz ilerleyecek, değil mi?"
  },
  Stage_7837_Name = {
    Text = "Görünüş Aldatır"
  },
  Stage_7838_Desc = {
    Text = "Tatlı, yoğun, Çocuklar tarafından çok sevilen.\nZarif, yüce, yetişkinlerin arzuladığı."
  },
  Stage_7838_Name = {
    Text = "Şekerimsi Sanat"
  },
  Stage_7839_Desc = {
    Text = "Vicdanın yükü, ağır bir yemin kadar ezici olabilir."
  },
  Stage_7839_Name = {
    Text = "Vicdan Yükü"
  },
  Stage_7840_Desc = {
    Text = "Tehlike içeriden gelir."
  },
  Stage_7840_Name = {
    Text = "İçsel Tehdit"
  },
  Stage_7841_Desc = {
    Text = "Keşke hiç büyümesem de, her gece seninle yıldızları seyredebilsem.\nKeşke daha çabuk büyüyebilsem de, hepinizi koruyabilsem."
  },
  Stage_7841_Name = {
    Text = "Sırrımız"
  },
  Stage_7842_Desc = {
    Text = "Kuklanın iplerini kesersen, bir daha asla dans etmeyecek."
  },
  Stage_7842_Name = {
    Text = "Kuşsuz Gece"
  },
  Stage_7843_Desc = {
    Text = "Aradığın her şey gözlerinin önünde duruyor. Sen sadece onu hiç idrak etmedin."
  },
  Stage_7843_Name = {
    Text = "Şapka Kenarının Altında"
  },
  Stage_7844_Desc = {
    Text = "Ramona ekibe yeniden katıldı. Mythag Müfettişi'nin yolculuğu sürüyor."
  },
  Stage_7844_Name = {
    Text = "Dünün Yeniden Doğuşu"
  },
  Stage_7845_Desc = {
    Text = "İnsan bacakları vahşi dört ayaklıların çevikliğine yetişemez, ama insan zihni yetişebilir.\nPeki, \"Cehennem Köpeği\" ni yakaladıktan sonra seni ne bekliyor?"
  },
  Stage_7845_Name = {Text = "Kozdaki As"},
  Stage_7846_Desc = {
    Text = "Size hoş bir yolculuk diliyorum."
  },
  Stage_7846_Name = {
    Text = "Uğurlu Yolculuk"
  },
  Stage_7847_Desc = {
    Text = "Metronun içinde, gizemli bir suikastçının saldırısına uğradın..."
  },
  Stage_7847_Name = {
    Text = "Dostsuz Hayat"
  },
  Stage_7848_Desc = {
    Text = "Leydi Nergis ile her etkileşim bir alışveriştir. Leydi Nergis belirir ve bir anlaşma teklif eder, fakat gizemli saldırgan bu alışverişi kabul edecek midir?"
  },
  Stage_7848_Name = {
    Text = "Adil Ticaret"
  },
  Stage_7849_Desc = {
    Text = "Cehennem Köpeği \"Kerberos\" hakkındaki söylentilerin ardından, Mythag Müfettişleri, Londinium yakınlarındaki Rye adlı küçük kasabanın dışına varır; kayboluşların ardındaki gizemi ortaya çıkarmaya çalışırlar..."
  },
  Stage_7849_Name = {
    Text = "Önce Düşün Sonra Davran"
  },
  Stage_7850_Desc = {
    Text = "İyi haberler ve kötü haberler. Kaybedilen ipuçları geri dönmeyecek, ama gölgelerde yeni vakalar mayalanıyor.\nİnan, müfettişler bir daha eli boş dönmeyecek."
  },
  Stage_7850_Name = {
    Text = "İyi Haber, Kötü Haber"
  },
  Stage_7851_Desc = {
    Text = "Çılgın bir tını; kanlı bir koku—bu, Rye’ın hoş geldin töreni."
  },
  Stage_7851_Name = {
    Text = "Çavdar'a Hoş Geldin"
  },
  Stage_7852_Desc = {
    Text = "Uysal bir dinlenme ve toparlanma hâlinde, yatağın kenarına yaslanmıştır; donuk düğme gözleri boşluğa dikilidir.\nKüçük beden, sahibinin tüm gözyaşlarını taşımıştır, ama tek bir teselli sözü sunamaz."
  },
  Stage_7852_Name = {
    Text = "Kuklanın Gözyaşları III"
  },
  Stage_7855_Desc = {
    Text = "O, O olamaz, ve O asla o olamaz.\nEvet... Evet, yalnızca benim Tanrım gerçek O’dur."
  },
  Stage_7855_Name = {
    Text = "Yitik Işık"
  },
  Stage_7856_Desc = {
    Text = "Onlar, Yıldızlar doğmadan çok önce var oldular.\nOnlar hem Düş hem de her şeydir."
  },
  Stage_7856_Name = {
    Text = "Bulanık Kalıntı IV"
  },
  Stage_7857_Desc = {
    Text = "Okyanusun Sır larını Sessizlik içinde Muhafız lık ederek korurlar; ruhları, kozmos kadar dipsizdir."
  },
  Stage_7857_Name = {
    Text = "Uçurum Kalıntısı II"
  },
  Stage_7858_Desc = {
    Text = "Bir gün batımı sonsuza dek nasıl tahammül edebilir?"
  },
  Stage_7858_Name = {
    Text = "Günbatımı"
  },
  Stage_7859_Desc = {
    Text = "Yağmur indiğinde ve kan dalgalandığında, kavuşma anı gelir.\nUzun zaman oldu, Koruyucu."
  },
  Stage_7859_Name = {
    Text = "Tesadüfi Kesişme"
  },
  Stage_7860_Desc = {
    Text = "Zaman ile mekânın aralıklarında, anlaşılmaz büyücüler gibi sürüklenirler.\nNe nefret, ne korku, ne de merhamet taşırlar."
  },
  Stage_7860_Name = {
    Text = "Kozmik Kalıntı I"
  },
  Stage_7861_Desc = {
    Text = "İhlalcileri durmaksızın kovalar.\n \"Kurallar\"ı neyin oluşturduğu ve neyin onları \"çiğnemek\" sayıldığına gelince?\nTazı asla düşünmez—düşünmek kovalamacayı yalnızca yavaşlatır."
  },
  Stage_7861_Name = {
    Text = "Diyar Ötesi Gölge IV"
  },
  Stage_7862_Desc = {
    Text = "Okyanusun Sır larını Sessizlik içinde Muhafız lık ederek korurlar; ruhları, kozmos kadar dipsizdir."
  },
  Stage_7862_Name = {
    Text = "Uçurum Kalıntısı III"
  },
  Stage_7863_Desc = {
    Text = "Okyanusun Sır larını Sessizlik içinde Muhafız lık ederek korurlar; ruhları, kozmos kadar dipsizdir."
  },
  Stage_7863_Name = {
    Text = "Uçurum Kalıntısı I"
  },
  Stage_7864_Desc = {
    Text = "Londinium, göz kamaştırıcı endüstriyel uygarlığı ve şehri saran kurşuni sisiyle Ünlü’dür.\nSis her yerdedir—yoldan geçenler için, önemsiz, anlamsız bir rahatsızlıktan fazlası değildir."
  },
  Stage_7864_Name = {
    Text = "Büyük Duman Şehri I"
  },
  Stage_7865_Desc = {
    Text = "Onun gözlerini ne kör etti?\nSevgi mi, merhamet mi, adalet mi—yoksa aşırı bir minnettarlık mı?"
  },
  Stage_7865_Name = {
    Text = "Aşkınlık"
  },
  Stage_7866_Desc = {
    Text = "Çocuk, acıyla dolu bir kucaklayış için yalvararak annesine uzanır.\nEnjeksiyon iğnesi narin tenini delerken, neşter solgun etini yararken ve bağlar Kırılgan eklemlerini sıkıca kavrarken bile.\nBüyüyen, sonu gelmez acı bile kucaklaşmalarını durduramaz.\nÇünkü bu en sıcak kucaklayıştır—embriyo annesinin rahmini terk ettiği andan itibaren yabancılaşma büyür; keskinlik bilenir; karşılıklı yara açılır—ve nihayetinde yeniden yakınlığa dönülür, tek bir bedende kaynaşılır."
  },
  Stage_7866_Name = {Text = "O"},
  Stage_7867_Desc = {
    Text = "Gecenin dinginliğinde uyursun, ne kuşku kalır ne de çekişme;\nsanki ebedî bir kucaklayış gibi, dingin bir huzur içinde dinleniriz."
  },
  Stage_7867_Name = {Text = "Oda"},
  Stage_7868_Desc = {
    Text = "Zambaklar karlı ovalara yayılıp açıyor."
  },
  Stage_7868_Name = {
    Text = "Gizemli Nehir"
  },
  Stage_7869_Desc = {
    Text = "Şafak her zaman gelir. Güneş mutlaka doğar."
  },
  Stage_7869_Name = {Text = "Son Söz"},
  Stage_7870_Desc = {
    Text = "Kutsal kalıntıyı kendi etinde taşır, mümini doktrinle güder ve inancı zehirli dişleriyle yayar."
  },
  Stage_7870_Name = {
    Text = "Dindarlık Kavrayışı II"
  },
  Stage_7871_Desc = {
    Text = "Keskin dikenler, önceden kusursuz olan yayı delip geçti—yarıktan beliren şey \"Kerberos\" tan başka bir varlıktı."
  },
  Stage_7871_Name = {
    Text = "Çatlak Kabuk"
  },
  Stage_7872_Desc = {
    Text = "Gerçeklik yıkımın tohumlarını ekerken, kader karşılaşmayı yönlendirir."
  },
  Stage_7872_Name = {
    Text = "Kaderin Tohumu"
  },
  Stage_78738_Name = {
    Text = "Tulu: Tanrı Kral Deneme Bölümü"
  },
  Stage_7873_Desc = {
    Text = "Onlar karanlıkta bükülüp birleşir, sonra putların içinde itinayla saklanır.\nBu, önceden tasarlanmış bir kavuşmadır."
  },
  Stage_7873_Name = {
    Text = "Aequor Mirası: Çatlak V"
  },
  Stage_7874_Desc = {
    Text = "Bir gemide, Kaptan'dan başka kime güvenilebilir?"
  },
  Stage_7874_Name = {
    Text = "Mürettebat Üyesi"
  },
  Stage_7875_Desc = {
    Text = "Denizin Havarisi."
  },
  Stage_7875_Name = {Text = "Havari"},
  Stage_7876_Desc = {
    Text = "Nice denizleri aşarken—düşmanların yanı sıra, belki bir parıltı kadar umut da vardır."
  },
  Stage_7876_Name = {Text = "Müptela"},
  Stage_78773_Name = {
    Text = "Murphy: Sahte Doğumlu Deneme Bölümü"
  },
  Stage_7877_Desc = {
    Text = "Onlar, ağıt, Bükülme ve saflığın bilinçsiz bir bileşimiydi;\nneşeli Çocuklar, yetişkinler ve evcil hayvanlar kılığına bürünmüşlerdi.\nHiç mutluluk tatmadıkları için, hepsi en kötü oyunculara dönüştü."
  },
  Stage_7877_Name = {
    Text = "Heykelin Sırları II"
  },
  Stage_7878_Desc = {
    Text = "Gece vakti liman, sade Sakinler ve onların sıcak misafirperverliği."
  },
  Stage_7878_Name = {
    Text = "Dört Bir Yandan Pusu"
  },
  Stage_7879_Desc = {
    Text = "Bilinmeyen kökenli putlar karanlıkta dolaşır, titrer.\nUzak bir flütün sesine kapılıp, kadim ritimlere göre hareket ederler."
  },
  Stage_7879_Name = {
    Text = "Caro Bataklığı: Çatlak VIII"
  },
  Stage_7880_Desc = {
    Text = "Yarıp geçmek asla kolay değildir. Ama bu kez, Koruyucu gökkubbedeki en parlak yıldızı buldu."
  },
  Stage_7880_Name = {
    Text = "Yıldızların Peşinde"
  },
  Stage_7881_Desc = {
    Text = "Murphy’nin içinde ikinci bir kalp atıyor—yaklaşan \"Doğum Ritüeli\" ni engellemeliyiz."
  },
  Stage_7881_Name = {
    Text = "Bir Başka Mucize"
  },
  Stage_7882_Desc = {
    Text = "Bilinmeyen kökenli putlar karanlıkta dolaşır, titrer.\nUzak bir flütün sesine kapılıp, kadim ritimlere göre hareket ederler."
  },
  Stage_7882_Name = {
    Text = "Kaos Diyarı: Çatlak VII"
  },
  Stage_7883_Desc = {
    Text = "Gerçeklik—acımasız, amansız gerçeklik."
  },
  Stage_7883_Name = {
    Text = "Peçenin Ardında"
  },
  Stage_7884_Desc = {
    Text = "Sessiz alev, yanından geçenlere içi boş vaatler fısıldar."
  },
  Stage_7884_Name = {
    Text = "Güve Kapanı Ateşi"
  },
  Stage_7885_Desc = {
    Text = "Kaderin fırtınalı rüzgârlarında titreyip çırpınabilirsin, ama asla gerçekten savrulup kaybolmayacaksın."
  },
  Stage_7885_Name = {
    Text = "Uçurum Kenarı"
  },
  Stage_7886_Desc = {
    Text = "Siste sarmalanmış izler, üzerlerinde dolaşan sayısız ayak sesleri—her adım, kadere yöneltilmiş bir soru."
  },
  Stage_7886_Name = {Text = "Sapan Yol"},
  Stage_7887_Desc = {
    Text = "Dökülen put, halkına bakar;\nOnların hayatta kalışını, çoğalışını, savaşını—andan sonra da onu tümden unutmalarını seyreder.\nDökülen put, halkını özler..."
  },
  Stage_7887_Name = {
    Text = "Hayali Dalış IV"
  },
  Stage_7888_Desc = {
    Text = "Kaba, sindirilmemiş bir yığın. İnsanlar ona dışkı—ya da kaos—der.\nDünya, dışkıdan doğdu."
  },
  Stage_7888_Name = {
    Text = "Kaos Kümesi I"
  },
  Stage_7889_Desc = {
    Text = "Ölü Ruh unutulduğunda, her şey normale döner.\nYine de solan Anıları her zaman hatırlayacak biri kalır."
  },
  Stage_7889_Name = {
    Text = "Her Zamanki Gibi"
  },
  Stage_7890_Desc = {
    Text = "\"O Bir’dir. O Tüm’dür. O, Hakikat’in kapısını açan umuttur.\"\nSayısız anahtar bir çember oluşturdu. Gökyüzünden düşerek, insanlığa ağır bir umut getirdiler.\nVe ağır mezarlar."
  },
  Stage_7890_Name = {
    Text = "Hayali Dalış V"
  },
  Stage_7891_Desc = {
