  Stage_7944_Name = {
    Text = "Hayali Dalış II"
  },
  Stage_7945_Desc = {
    Text = "O, rüyalarla gerçeğin iç içe geçtiği sınırdır—gece göğüne bakan her ruhun derinliklerinde yaşayan yansımadır."
  },
  Stage_7945_Name = {
    Text = "Çarpık Yıldızlar"
  },
  Stage_7945_StageInitStateText = {
    Text = "Deniz Kabusu"
  },
  Stage_7946_Desc = {
    Text = "Kozmosun derinliklerinde gizlenen eğri ufuk.\nSeni bir karanlıktan alıp diğerine götürür."
  },
  Stage_7946_Name = {
    Text = "Schwarzschild Boğazı I"
  },
  Stage_7947_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_7947_Name = {
    Text = "Kaos Diyarı: Çatlak III"
  },
  Stage_7948_Desc = {
    Text = "Burada, hafif uykuda bir kadim kentin harabeleri yatıyor.\nEfendisi kadar derin uyur."
  },
  Stage_7948_Name = {
    Text = "Pohnpei Harabeleri V"
  },
  Stage_7949_Desc = {
    Text = "Uysal bir dinlenme ve toparlanma hâlinde, yatağın kenarına yaslanmıştır; donuk düğme gözleri boşluğa dikilidir.\nKüçük beden, sahibinin tüm gözyaşlarını taşımıştır, ama tek bir teselli sözü sunamaz."
  },
  Stage_7949_Name = {
    Text = "Kuklanın Gözyaşları II"
  },
  Stage_7950_Desc = {
    Text = "Sağlığın ve canın için nikotinden uzak dur."
  },
  Stage_7950_Name = {
    Text = "Duman ve Menekşe"
  },
  Stage_7951_Desc = {
    Text = "Bilinmeyen kökenli putlar karanlıkta dolaşır, titrer.\nUzak bir flütün sesine kapılıp, kadim ritimlere göre hareket ederler."
  },
  Stage_7951_Name = {
