  },
  Stage_7952_Desc = {
    Text = "Et ve kandan dövülmüş gerçeği sun—onlar doyumsuz bir uçurumdur."
  },
  Stage_7952_Name = {
    Text = "Organik Kalıntı III"
  },
  Stage_7953_Desc = {
    Text = "Dökülen put, halkına bakar;\nOnların hayatta kalışını, çoğalışını, savaşını—andan sonra da onu tümden unutmalarını seyreder.\nDökülen put, halkını özler..."
  },
  Stage_7953_Name = {
    Text = "Hayali Dalış II"
  },
  Stage_7954_Desc = {
    Text = "Sonra kayboldu, karanlık tarafından yutuldu.\nİnsanlar başlarını kaldırdı, gözleri faltaşı gibi açılmış, onun katettiği göğe bakıyorlardı."
  },
  Stage_7954_Name = {
    Text = "Ardıç Ağacı"
  },
  Stage_7955_Desc = {
    Text = "Onun güzelliğinin sunağına gözyaşlarımı, iç çekişlerimi ve gerçek kalbimi sunuyorum."
  },
  Stage_7955_Name = {Text = "Galatea"},
  Stage_7956_Desc = {
    Text = "Dökülen put, halkına bakar;\nOnların hayatta kalışını, çoğalışını, savaşını—andan sonra da onu tümden unutmalarını seyreder.\nDökülen put, halkını özler..."
  },
  Stage_7956_Name = {
    Text = "Hayali Dalış V"
  },
  Stage_79574_Desc = {
    Text = "Açığa vurulmuş bir kalp, kadim bir numune, soluk bir Gümüş Anahtar—\naleve çekilen bir güve gibi, onun beklediği, yalnızca senin getirebileceğin bir vedadır."
  },
  Stage_79574_Name = {
    Text = "Ateş Güvesi·Bölüm IV"
  },
  Stage_79575_Desc = {
    Text = "Kadim gümüş ışık, kıza üçüncü bir hayat bahşeder.\nSon gözyaşları diner ve Ebedi Izdırap başlar.\nİlk yeni damla iner ve Yeni Bölüm açılır.\nÖlüme yürümüş olan, gerçek benliğini aramak için yeniden yola çıkar."
  },
  Stage_79575_Name = {
    Text = "\"Yeniden Doğuş\"·Bölüm I"
  },
  Stage_79576_Desc = {
    Text = "Açığa vurulmuş bir kalp, kadim bir numune, soluk bir Gümüş Anahtar—\naleve çekilen bir güve gibi, onun beklediği, yalnızca senin getirebileceğin bir vedadır."
  },
  Stage_79576_Name = {
    Text = "Ateş Güvesi·Bölüm V"
  },
  Stage_79577_Desc = {
