  },
  Stage_79588_Desc = {
    Text = "Bu andan itibaren, benimle hiçbir birikim saklamadan konuş—Anılarını önümde çıplak bırak.\nBu andan itibaren, tereddütsüz itaat et bana—Zihnini korumama teslim et.\nSeni, hafızanın derinliklerinde yaşayan en gerçek benliğine dönüştüreceğim."
  },
  Stage_79588_Name = {
    Text = "Hafıza Kliniği·Bölüm II"
  },
  Stage_79589_Desc = {
    Text = "Bu andan itibaren, benimle hiçbir birikim saklamadan konuş—Anılarını önümde çıplak bırak.\nBu andan itibaren, tereddütsüz itaat et bana—Zihnini korumama teslim et.\nSeni, hafızanın derinliklerinde yaşayan en gerçek benliğine dönüştüreceğim."
  },
