  Stage_79608_Name = {
    Text = "İstila Edilen Düşler·Bölüm II"
  },
  Stage_7960_Desc = {
    Text = "Ne kutlu bir hafif uyku—meleğimi bana geri getiriyor."
  },
  Stage_7960_Name = {
    Text = "Gizli Pencere"
  },
  Stage_7961_Desc = {
    Text = "Günlükler, Hafıza’nın parçalarıdır.\nGünlükler daima Soruşturmalar sırasında keşfedilir."
  },
  Stage_7961_Name = {
    Text = "Hafıza Parçaları"
  },
  Stage_7962_Desc = {
    Text = "Zambaklar karlı ovalara yayılıp açıyor."
  },
  Stage_7962_Name = {Text = "28 Gün"},
  Stage_7963_Desc = {
    Text = "Soylular güçlerini, zenginler servetlerini yitirdiğinde, çaresiz kalırlar—tıpkı şu anda senin gibi."
  },
  Stage_7963_Name = {
    Text = "Guguk Kuşu Sığınağı"
  },
  Stage_7964_Desc = {
    Text = "Onun için yaratılmış bir diyar—derin bir aşk ve dehşet verici bir kafes, ikisi de aynı şey."
  },
  Stage_7964_Name = {Text = "Tımarhane"},
  Stage_7965_Desc = {
    Text = "Çatışma, yalnızca savaş alanına hapsedilemez. Bazen delilerin hezeyanlarında ikamet eder."
  },
  Stage_7965_Name = {
    Text = "Delinin Ağzı"
  },
  Stage_7966_Desc = {
    Text = "Sessiz alev, yanından geçenlere içi boş vaatler fısıldar."
  },
  Stage_7966_Name = {
    Text = "Güve Kapanı Ateşi"
  },
  Stage_7967_Desc = {
    Text = "Siste sarmalanmış izler, üzerlerinde dolaşan sayısız ayak sesleri—her adım, kadere yöneltilmiş bir soru."
  },
  Stage_7967_Name = {Text = "Sapan Yol"},
  Stage_7968_Desc = {
    Text = "İhlalcileri durmaksızın kovalar.\n \"Kurallar\"ı neyin oluşturduğu ve neyin onları \"çiğnemek\" sayıldığına gelince?\nTazı asla düşünmez—düşünmek kovalamacayı yalnızca yavaşlatır."
  },
  Stage_7968_Name = {
    Text = "Diyar Ötesi Gölge I"
  },
  Stage_7969_Desc = {
    Text = "Kutsal kalıntıyı kendi etinde taşır, mümini doktrinle güder ve inancı zehirli dişleriyle yayar."
  },
  Stage_7969_Name = {
    Text = "Dindarlık Kavrayışı I"
  },
  Stage_7970_Desc = {
    Text = "Fırtına hâlâ kaynıyor. Henüz bitmedi."
  },
  Stage_7970_Name = {
    Text = "Gerçeklik Yeniden Başlatma"
  },
  Stage_7971_Desc = {
    Text = "O, asla arzu edilmiş bir varlık değildi; yalnızca pis bir parazitti."
  },
  Stage_7971_Name = {Text = "Parazit"},
  Stage_7972_Desc = {
    Text = "Karaya doğru yelken aç—bir umut parıltısına doğru."
  },
  Stage_7972_Name = {
    Text = "Trajik Yola Çıkış"
  },
  Stage_7973_Desc = {
    Text = "Gece, Akıntılar tarafından kemiriliyor ve yıldızlar susuyor. Kıvrımlarla ve fırtınalarla yüklü Kriz Ayı, sessizce bilinmeyen bir geleceği yansıtıyor."
  },
  Stage_7973_Name = {Text = "Kriz Ayı"},
  Stage_7974_Desc = {
    Text = "Gecenin sonsuz Karanlığında, baştan çıkarıcı ışığın peşine düşmek; alevlere çekilen bir güve gibi, yazgının alevlerine, geride hiçbir şey bırakmadan kanat çırpmak."
  },
  Stage_7974_Name = {
    Text = "Alevi Kovalayan Güve"
  },
  Stage_7975_Desc = {
    Text = "Yılların geçidi boyunca tahammül eden dostluklar, yeni bir umut filizlendirdi."
  },
  Stage_7975_Name = {
    Text = "Eski Dostlar, Yeni Bağlar"
  },
  Stage_7976_Desc = {
    Text = "Kaderin fırtınalı rüzgârlarında titreyip çırpınabilirsin, ama asla gerçekten savrulup kaybolmayacaksın."
  },
  Stage_7976_Name = {
    Text = "Uçurum Kenarı"
  },
  Stage_7977_Desc = {
    Text = "Rüzgâra ve kumlara karşı, savaşçı tereddütsüz güneşe doğru şarj eder."
  },
  Stage_7977_Name = {
    Text = "Güneş Seferi"
  },
  Stage_7978_Desc = {
    Text = "Kıvranarak, sızarak... O protoplazmik kütle, Zincirler’inin çatlaklarından süzülür.\nBu, onun \"özgürlük\" için ödediği bedeldir."
  },
  Stage_7978_Name = {
    Text = "Karanlık Zinciri V"
  },
  Stage_7979_Desc = {
    Text = "Kaba, sindirilmemiş bir yığın. İnsanlar ona dışkı—ya da kaos—der.\nDünya, dışkıdan doğdu."
  },
  Stage_7979_Name = {
    Text = "Kaos Kümesi III"
  },
  Stage_7980_Desc = {
    Text = "Bilinmeyen kökenli putlar karanlıkta dolaşır, titrer.\nUzak bir flütün sesine kapılıp, kadim ritimlere göre hareket ederler."
  },
  Stage_7980_Name = {
    Text = "Ultra Yolculuğu: Çatlak VIII"
  },
  Stage_7981_Desc = {
    Text = "Onlar karanlıkta bükülüp birleşir, sonra putların içinde itinayla saklanır.\nBu, önceden tasarlanmış bir kavuşmadır."
  },
  Stage_7981_Name = {
    Text = "Caro Bataklığı: Çatlak V"
  },
  Stage_7982_Desc = {
    Text = "Sonra kayboldu, karanlık tarafından yutuldu.\nİnsanlar başlarını kaldırdı, gözleri faltaşı gibi açılmış, onun katettiği göğe bakıyorlardı."
  },
  Stage_7982_Name = {
    Text = "Ardıç Ağacı"
  },
  Stage_7983_Desc = {
    Text = "Bir küçük fare, bir küçük fare.\nKoş, koş! Onun kuyruğunu satırla kesti."
  },
  Stage_7983_Name = {
    Text = "Brown'un Hücumu"
  },
  Stage_7984_Desc = {
    Text = "Gecenin dinginliğinde uyursun, ne kuşku kalır ne de çekişme;\nsanki ebedî bir kucaklayış gibi, dingin bir huzur içinde dinleniriz."
  },
  Stage_7984_Name = {Text = "Oda"},
  Stage_7985_Desc = {
    Text = "Londinium, göz kamaştırıcı endüstriyel uygarlığı ve şehri saran kurşuni sisiyle Ünlü’dür.\nSis her yerdedir—yoldan geçenler için, önemsiz, anlamsız bir rahatsızlıktan fazlası değildir."
  },
  Stage_7985_Name = {
    Text = "Büyük Duman Şehri III"
  },
  Stage_7986_Desc = {
    Text = "Onun güzelliğinin sunağına gözyaşlarımı, iç çekişlerimi ve gerçek kalbimi sunuyorum."
  },
  Stage_7986_Name = {Text = "Galatea"},
  Stage_7987_Desc = {
    Text = "Çat—bölünür.\nÇıt—kırılır."
  },
  Stage_7987_Name = {
    Text = "Oyuncak Evi"
  },
  Stage_7988_Desc = {
    Text = "Kurallar çiğnenmek içindir, öyle değil mi?"
  },
  Stage_7988_Name = {Text = "Üç Kural"},
  Stage_7989_Desc = {
    Text = "Kuzey Yorkshire’da bir sahil kasabası—Scarborough. Yükselen kayalıkları ve altın rengi koylarıyla zarif ve büyüleyici bir tatil beldesi."
  },
  Stage_7989_Name = {
    Text = "Scarborough Yazı"
  },
  Stage_7990_Desc = {
    Text = "Ah, kollar, şu baş belası kollar! Saçımı çekip duruyorlar."
  },
  Stage_7990_Name = {Text = "24"},
  Stage_7991_Desc = {
    Text = "İnsan gözyaşlarından ve dışkısından, herhangi bir kitaptan öğrendiğinden daha fazla pratik psikoloji devşirdi."
  },
  Stage_7991_Name = {
    Text = "Sıhhiye El Kitabı"
  },
  Stage_7992_Desc = {
    Text = "Sağlığın ve canın için nikotinden uzak dur."
  },
  Stage_7992_Name = {
    Text = "Duman ve Menekşe"
  },
  Stage_7993_Desc = {
    Text = "Kuzey Yorkshire’da bir sahil kasabası—Scarborough. Yükselen kayalıkları ve altın rengi koylarıyla zarif ve büyüleyici bir tatil beldesi."
  },
  Stage_7993_Name = {
    Text = "Scarborough Yazı"
  },
  Stage_7994_Desc = {
    Text = "Sağlığın ve canın için nikotinden uzak dur."
  },
  Stage_7994_Name = {
    Text = "Duman ve Menekşe"
  },
  Stage_7995_Desc = {
    Text = "Bir küçük fare, bir küçük fare.\nKoş, koş! Onun kuyruğunu satırla kesti."
  },
  Stage_7995_Name = {
    Text = "Brown'un Hücumu"
  },
  Stage_7996_Desc = {
    Text = "Sonra kayboldu, karanlık tarafından yutuldu.\nİnsanlar başlarını kaldırdı, gözleri faltaşı gibi açılmış, onun katettiği göğe bakıyorlardı."
  },
  Stage_7996_Name = {
    Text = "Ardıç Ağacı"
  },
  Stage_7997_Desc = {
    Text = "Onun güzelliğinin sunağına gözyaşlarımı, iç çekişlerimi ve gerçek kalbimi sunuyorum."
  },
  Stage_7997_Name = {Text = "Galatea"},
  Stage_7998_Name = {Text = "[Prologue]"},
  Stage_7999_Desc = {
    Text = "Ah, kollar, şu baş belası kollar! Saçımı çekip duruyorlar."
  },
  Stage_7999_Name = {Text = "24"},
  Stage_8000_Desc = {
    Text = "Elbette, elbette. Gözler zihnin zindanı; ruh ise bedenin prangasıdır."
  },
  Stage_8000_Name = {
    Text = "Anatominin Melankolisi"
  },
  Stage_8001_Desc = {
    Text = "Aynen öyle, bebeğim. İstediğin kadar ağla ve acını bir başyapıt gibi çerçevele."
  },
  Stage_8001_Name = {
    Text = "Kız ve Gözyaşları"
  },
  Stage_8002_Desc = {
    Text = "\"El\", gecenin perdesini aralar, sessizce bu dünyaya Dönüş yapar."
  },
  Stage_8002_Name = {
    Text = "Hayali Dalış I"
  },
  Stage_8003_Desc = {
    Text = "\"El\", gecenin perdesini aralar, sessizce bu dünyaya Dönüş yapar."
  },
