  Stage_80271_Desc = {
    Text = "Ufacık bir Kelebek, düşler arasından süzülüp gerçeğe karışır.\nBelki fazlasıyla saf olabilir, ama kelebeğin seçimi insanınkinden farklıdır."
  },
  Stage_80271_Name = {
    Text = "Kelebek Uçuşu"
  },
  Stage_8027_Desc = {
    Text = "Çatışma, yalnızca savaş alanına hapsedilemez. Bazen delilerin hezeyanlarında ikamet eder."
  },
  Stage_8027_Name = {
    Text = "Delinin Ağzı"
  },
  Stage_8028_Desc = {
    Text = "Kuklanın iplerini kesersen, bir daha asla dans etmeyecek."
  },
  Stage_8028_Name = {
    Text = "Kuşsuz Gece"
  },
  Stage_8029_Desc = {
    Text = "Geriye bakma—ne kıymetli bir öğüt. Orpheus'un ayak seslerini izleme."
  },
  Stage_8029_Name = {
    Text = "Arkana Bakma"
  },
  Stage_8030_Desc = {
    Text = "\"Primavera\"nın ardındaki gerçek anlamı kim belirleyebilir ki?\nÖlüm ve unutuş, sessiz boşlukta uykuda yatar; bir bahar gününün bulanık serabıyla birleşir."
  },
  Stage_8030_Name = {
    Text = "《Botticelli'nin Baharı》"
  },
  Stage_8031_Desc = {
    Text = "Günlükler, Hafıza’nın parçalarıdır.\nGünlükler daima Soruşturmalar sırasında keşfedilir."
  },
  Stage_8031_Name = {
    Text = "Hafıza Parçaları"
  },
  Stage_8032_Desc = {
    Text = "Tanıştığımıza memnun oldum, efendim."
  },
  Stage_8032_Name = {
    Text = "Altıncı His"
  },
  Stage_8033_Desc = {
    Text = "Onlar karanlıkta bükülüp birleşir, sonra putların içinde itinayla saklanır.\nBu, önceden tasarlanmış bir kavuşmadır."
  },
  Stage_8033_Name = {
    Text = "Caro Bataklığı: Çatlak VI"
  },
  Stage_8034_Desc = {
    Text = "Onlar, Yıldızlar doğmadan çok önce var oldular.\nOnlar hem Düş hem de her şeydir."
  },
  Stage_8034_Name = {
    Text = "Bulanık Kalıntı III"
  },
  Stage_8035_Desc = {Text = "Rastgele 4"},
  Stage_8035_Name = {
    Text = "Ay Bataklığı Aynası IV"
  },
  Stage_8036_Desc = {Text = "Rastgele 5"},
  Stage_8036_Name = {
    Text = "Ay Bataklığı Aynası V"
  },
  Stage_8037_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_8037_Name = {
    Text = "Kaos Diyarı: Dönüşüm Aralığı I"
  },
  Stage_8038_Desc = {Text = "Rastgele 1"},
  Stage_8038_Name = {
    Text = "Ay Bataklığı Aynası I"
  },
  Stage_8039_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_8039_Name = {
    Text = "Kaos Diyarı: Dönüşüm Aralığı I"
  },
  Stage_8040_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_8040_Name = {
    Text = "Kaos Diyarı: Dönüşüm Aralığı I"
  },
  Stage_8041_Desc = {
    Text = "Ramona ekibe yeniden katıldı. Mythag Müfettişi'nin yolculuğu sürüyor."
  },
  Stage_8041_Name = {
    Text = "Dünün Yeniden Doğuşu"
  },
  Stage_8042_Desc = {
    Text = "Issız demiryolu köprüsünün altında, devasa, şişkin bir Canavar tuhaf hırıltılar salar. Rye Sanatoryumu’na ulaşmak için önce buradan geçmelisin."
  },
  Stage_8042_Name = {
    Text = "Akıntı Seni Yönlendirecek"
  },
  Stage_8043_Desc = {
    Text = "Aradığın her şey gözlerinin önünde duruyor. Sen sadece onu hiç idrak etmedin."
  },
  Stage_8043_Name = {
    Text = "Şapka Kenarının Altında"
  },
  Stage_8044_Desc = {
    Text = "Can, bir sarmal gibidir. Bir zamanlar kaçtığın karabasanlar, her gece yarısı seni sahiplenmek için geri döner."
  },
  Stage_8044_Name = {
    Text = "Yaratılış Dönüşü"
  },
  Stage_8045_Desc = {
    Text = "Ramona ve Lotan'ın mırıltıları arasında, Koruyucu kafesin içinde bir rüyanın derinliklerine iner."
  },
  Stage_8045_Name = {
    Text = "Bozulmamış Kutsallık"
  },
  Stage_8046_Desc = {
    Text = "Tanrı, onların acıya tahammül etmek ve son damlasına dek kanlarının akıtılmak için doğduğunu söyledi.\nNasıl güneş doğmak, yağmur yağmak zorundaysa.\nHer şey olması gerektiği gibidir."
  },
  Stage_8046_Name = {
    Text = "Acı Yağmur"
  },
  Stage_8047_Desc = {
    Text = "Rogers Balmumu Müzesi, Southwark Caddesi’nin en ucunda, Taym’in bir koluna yakın bir yerde durur.\nGörünüşte gösterişsizdir, ama Uzaklardan Avangard Sanat meraklılarını kendine çeker."
  },
  Stage_8047_Name = {
    Text = "Çılgın Balmumu Müzesi II"
  },
  Stage_8048_Desc = {
    Text = "Buradaki tek canlı odur, gördüğü her şey üzerinde hüküm sürer.\n—O, yüce kraldır."
  },
  Stage_8048_Name = {
    Text = "Yaban Hayvanı Krallığı"
  },
  Stage_8049_Desc = {
    Text = "Onun hükümranlığı, kozmosun kabuğudur ve arzuları sınır tanımaz."
  },
  Stage_8049_Name = {
    Text = "Solucan Yuvası I"
  },
  Stage_8050_Desc = {
    Text = "\"El\", gecenin perdesini aralar, sessizce bu dünyaya Dönüş yapar."
  },
  Stage_8050_Name = {
    Text = "Hayali Dalış V"
  },
  Stage_8051_Desc = {
    Text = "Dökülen put, halkına bakar;\nOnların hayatta kalışını, çoğalışını, savaşını—andan sonra da onu tümden unutmalarını seyreder.\nDökülen put, halkını özler..."
  },
  Stage_8051_Name = {
    Text = "Hayali Dalış II"
  },
  Stage_8052_Desc = {
    Text = "Dökülen put, halkına bakar;\nOnların hayatta kalışını, çoğalışını, savaşını—andan sonra da onu tümden unutmalarını seyreder.\nDökülen put, halkını özler..."
  },
  Stage_8052_Name = {
    Text = "Hayali Dalış III"
  },
  Stage_8053_Desc = {
    Text = "Bu, sonu olmayan bir film. O, yıllardır ara gösterimi hafif uykuda geçirdi.\nYaz öğleden sonralarında gülleri—ve külleri, ve rüzgârı düşlüyor..."
  },
  Stage_8053_Name = {
    Text = "Felin Esin Perisi"
  },
  Stage_8054_Desc = {
