  Stage_8057_Name = {
    Text = "Hayali Dalış V"
  },
  Stage_8058_Desc = {
    Text = "Yağmur indiğinde ve kan dalgalandığında, kavuşma anı gelir.\nUzun zaman oldu, Koruyucu."
  },
  Stage_8058_Name = {
    Text = "Tesadüfi Kesişme"
  },
  Stage_8060_Desc = {
    Text = "Gölge geceye çözündüğünde ve damlalar yağmurla birleştiğinde,\nav saati yaklaşır..."
  },
  Stage_8060_Name = {
    Text = "Fırtına Yarığı"
  },
  Stage_8062_Desc = {
    Text = "Biz böceklerin, kemiklerin ve gözyaşlarının bir bileşimiyiz.\nBu gece burada tek bir amaç için toplanıyoruz—sayısız gökkuşağıyla akan nehri seyretmek için."
  },
  Stage_8062_Name = {
    Text = "Kafatası Avı Toplantısı"
  },
  Stage_8063_Desc = {
    Text = "\"O Bir’dir. O Tüm’dür. O, Hakikat’in kapısını açan umuttur.\"\nSayısız anahtar bir çember oluşturdu. Gökyüzünden düşerek, insanlığa ağır bir umut getirdiler.\nVe ağır mezarlar."
  },
