  },
  Stage_8102_Name = {
    Text = "Aequor Mirası: Dönüşüm Aralığı I"
  },
  Stage_8103_Name = {
    Text = "Apostle of the Sea Trial"
  },
  Stage_8104_Desc = {
    Text = "Rogers Balmumu Müzesi, Southwark Caddesi’nin en ucunda, Taym’in bir koluna yakın bir yerde durur.\nGörünüşte gösterişsizdir, ama Uzaklardan Avangard Sanat meraklılarını kendine çeker."
  },
  Stage_8104_Name = {
    Text = "Çılgın Balmumu Müzesi III"
  },
  Stage_8105_Desc = {
    Text = "Bir gün batımı sonsuza dek nasıl tahammül edebilir?"
  },
  Stage_8105_Name = {
    Text = "Günbatımı"
  },
  Stage_8106_Desc = {
    Text = "Keskin dikenler, önceden kusursuz olan yayı delip geçti—yarıktan beliren şey \"Kerberos\" tan başka bir varlıktı."
  },
  Stage_8106_Name = {
    Text = "Çatlak Kabuk"
  },
  Stage_8107_Desc = {
    Text = "Onun gözlerini ne kör etti?\nSevgi mi, merhamet mi, adalet mi—yoksa aşırı bir minnettarlık mı?"
  },
  Stage_8107_Name = {
    Text = "Aşkınlık"
  },
  Stage_8108_Desc = {
    Text = "Zaman ile mekânın aralıklarında, anlaşılmaz büyücüler gibi sürüklenirler.\nNe nefret, ne korku, ne de merhamet taşırlar."
  },
  Stage_8108_Name = {
    Text = "Kozmik Kalıntı IV"
  },
  Stage_8109_Desc = {
    Text = "\"Kapı\" açılmak üzere, gerçeğe dair bir parıltıyı ifşa ediyor.\nNe siyah ne beyaz—gerçek hem renkli hem bulanıktır."
  },
  Stage_8109_Name = {
    Text = "Aequor Mirası: Dönüşüm Aralığı I"
  },
  Stage_8110_Desc = {
    Text = "Cehennem Köpeği \"Kerberos\" hakkındaki söylentilerin ardından, Mythag Müfettişleri, Londinium yakınlarındaki Rye adlı küçük kasabanın dışına varır; kayboluşların ardındaki gizemi ortaya çıkarmaya çalışırlar..."
  },
  Stage_8110_Name = {
    Text = "Önce Düşün Sonra Davran"
  },
  Stage_8111_Desc = {
    Text = "İyi haberler ve kötü haberler. Kaybedilen ipuçları geri dönmeyecek, ama gölgelerde yeni vakalar mayalanıyor.\nİnan, müfettişler bir daha eli boş dönmeyecek."
  },
  Stage_8111_Name = {
    Text = "İyi Haber, Kötü Haber"
  },
  Stage_8112_Desc = {
    Text = "Gizemli “nergis” hanımefendi."
  },
  Stage_8112_Name = {
    Text = "Merhaba, Leydi Daffodil"
  },
  Stage_8113_Desc = {
    Text = "Çılgın bir tını; kanlı bir koku—bu, Rye’ın hoş geldin töreni."
  },
  Stage_8113_Name = {
    Text = "Çavdar'a Hoş Geldin"
  },
  Stage_8114_Desc = {
    Text = "İnsan bacakları vahşi dört ayaklıların çevikliğine yetişemez, ama insan zihni yetişebilir.\nPeki, \"Cehennem Köpeği\" ni yakaladıktan sonra seni ne bekliyor?"
  },
  Stage_8114_Name = {Text = "Kozdaki As"},
  Stage_8115_Desc = {
    Text = "Nergis sana \"cevabını\" getirdi. Tahtaya yeni bir taş adım atıyor, rüzgâr ve karla örülü bir düş getirerek."
