  },
  Stage_81784_Name = {
    Text = "D-Etki Bölgesi: Dalga 5: Delilik"
  },
  Stage_81785_Desc = {
    Text = "O görünmeyen felaket Canlanma bulur, bu maddi dünyanın geçmişini ve bugününü uçurumun derinliklerine yutar."
  },
  Stage_81785_Name = {
    Text = "D-Etki Bölgesi: Dalga 4: Delilik"
  },
  Stage_81786_Desc = {
    Text = "Kara Gelgit uyarı çizgisini aşarak kabarır; en hafif dalgalanma bile, dikkatsiz olanı yutabilecek tehlikeli bir tehdidi haber verir."
  },
  Stage_81786_Name = {
    Text = "D-Etkisi Yasak Bölgesi: Dalga 4: Seviye I Alarm"
  },
  Stage_81787_Desc = {
    Text = "O görünmeyen felaket Canlanma bulur, bu maddi dünyanın geçmişini ve bugününü uçurumun derinliklerine yutar."
  },
  Stage_81787_Name = {
    Text = "D-Etki Bölgesi: Dalga 5: Delilik"
  },
  Stage_81788_Desc = {
    Text = "Kara Gelgit uyarı çizgisini aşarak kabarır; en hafif dalgalanma bile, dikkatsiz olanı yutabilecek tehlikeli bir tehdidi haber verir."
  },
  Stage_81788_Name = {
    Text = "D-Etkisi Yasak Bölgesi: Dalga 2: Seviye I Alarm"
  },
  Stage_81789_Desc = {
    Text = "O görünmeyen felaket Canlanma bulur, bu maddi dünyanın geçmişini ve bugününü uçurumun derinliklerine yutar."
  },
  Stage_81789_Name = {
    Text = "D-Etki Bölgesi: Dalga 3: Delilik"
  },
  Stage_8178_Desc = {
    Text = "İnsanlar iradeleriyle dünyayı yeniden şekillendirir ve karşılığında onun tarafından yeniden şekillendirilirler."
  },
  Stage_8178_Name = {
