  },
  Stage_95334_Name = {
    Text = "Pazarlığın Çekirdeği·Çılgınlık"
  },
  Stage_95335_Desc = {
    Text = "Bedenindeki her hücre tek bir cümleyi tekrarlar, yalnızca onu tekrarlar: Işık burada."
  },
  Stage_95335_Name = {
    Text = "Dünyayı Saran Alev·Üçüncü"
  },
  Stage_95336_Desc = {
    Text = "Güneş toprağın üzerine iner, uçurumdan dehşet verici bir yükseliş. Her şey, yüceliğine bir ziyaret olarak eriyip akar."
  },
  Stage_95336_Name = {
    Text = "Yeryüzünün Güneşi·Üçüncü"
  },
  Stage_95337_Desc = {
    Text = "Güneş uçuruma geri döndüğünde dünya suskunluğa gömülecek. Çünkü geriye külden başka hiçbir şey kalmayacak."
  },
  Stage_95337_Name = {
    Text = "Sessiz Harabeler·Birinci"
  },
  Stage_95338_Desc = {
    Text = "Güneş uçuruma geri döndüğünde dünya suskunluğa gömülecek. Çünkü geriye külden başka hiçbir şey kalmayacak."
  },
  Stage_95338_Name = {
