  },
  Stage_95339_Name = {
    Text = "Sessiz Harabeler·Çılgınlık"
  },
  Stage_95340_Desc = {
    Text = "O sesi almaz; suçluların iniltilerini duymak ister.\nMilyarlarca ışık gece yarısı güneşinde dans eder, şarkıları çığlıklarla kusursuz bir uyum içinde birbirine dolanır."
  },
  Stage_95340_Name = {
