  },
  Stage_95341_Name = {
    Text = "Sessiz Harabeler·IV"
  },
  Stage_95342_Desc = {
    Text = "Hararetli alevlerle gelir, günahlarını ilan eder. Son kefaretin, direnmek; O’nu elinden geldiğince uzun süre eğlendirmektir."
  },
  Stage_95342_Name = {
    Text = "Kızıl Alev Hükmü: I"
  },
  Stage_95343_Desc = {
    Text = "Onun elini tutmak, Ölüm’le bir sözleşme imzalamaktır. Ödemenin vakti ise daima meçhuldür."
  },
  Stage_95343_Name = {
