    Text = "Anne, insanların doğumdan ölüme kadar fısıldadığı bir büyüdür.\nHiçbir çocuk büyümek istemez ve hiçbir çocuk annesinin sevgi dolu kucaklayışını özlemez değildir.\nO zalim kaderi bir kez daha oynayıp onu annesinin kollarından koparacak mısın?"
  },
  Stage_97834_Name = {
    Text = "Mükemmel Masal: I"
  },
  Stage_97835_Desc = {
    Text = "O biliyor: yalnızca pervasız cesaret, rakipsiz bir zaferi garanti edemez.\nO zaman da böyleydi, şimdi de böyle."
  },
  Stage_97835_Name = {
    Text = "Kıl Payı Zafer"
  },
  Stage_97836_Desc = {
    Text = "Güneş çoktan öldü; gökte, yalnızca yıpranmış bir ceset bıraktı.\nTıpkı bu çürüyen dünya gibi, kalın tozun içinde kalan şey, nihayetinde hayat mıdır, yoksa ölümünden önce kıpırdayan hayatın bir düşü mü?"
  },
  Stage_97836_Name = {
    Text = "Kara Güneşle Yüzleş: I"
  },
  Stage_97837_Desc = {
    Text = "Çetin savaş alanında, her yarışmacı kendine özgü bir hava sergiler...\nYönetmen, yayına uygun olmayan havaların hepsini kes."
  },
  Stage_97837_Name = {
    Text = "Başlasın! Yarı Final!"
  },
  Stage_97838_Desc = {
    Text = "Anne, insanların doğumdan ölüme kadar fısıldadığı bir büyüdür.\nHiçbir çocuk büyümek istemez ve hiçbir çocuk annesinin sevgi dolu kucaklayışını özlemez değildir.\nO zalim kaderi bir kez daha oynayıp onu annesinin kollarından koparacak mısın?"
  },
  Stage_97838_Name = {
    Text = "Mükemmel Masal: V"
  },
  Stage_97839_Desc = {
    Text = "Hem tanıdık hem yabancı gelen bir kampüste gezinirken, canlı ama sıradan olan her şeyi seyredersin. Bu manzarada sevinç ve hayranlık mı bulursun, yoksa hiç yaşamamış olduğun bu deneyimler için bir hüzün mü duyarsın?"
  },
  Stage_97839_Name = {
    Text = "Eski Yerlere Dönüş·Çılgınlık"
  },
  Stage_97840_Desc = {
    Text = "Ruhunu kaybettikten sonra bile ideallerini asla unutmadı.\nBilim uğruna ölenler, bir zamanlar bilim için tutkuyla yaşamışlardı."
  },
  Stage_97840_Name = {
    Text = "Bir Makinenin Rüyası: II"
  },
  Stage_97841_Desc = {
    Text = "Güneş çoktan öldü; gökte, yalnızca yıpranmış bir ceset bıraktı.\nTıpkı bu çürüyen dünya gibi, kalın tozun içinde kalan şey, nihayetinde hayat mıdır, yoksa ölümünden önce kıpırdayan hayatın bir düşü mü?"
  },
  Stage_97841_Name = {
    Text = "Kara Güneşle Yüzleş·Bölüm II"
  },
  Stage_97842_Desc = {
