  Stage_98836_Name = {
    Text = "Macera Masalı·IV"
  },
  Stage_98837_Desc = {
    Text = "Bu, Kader’in zalim bir merhametidir:\nhiçbir şey başlamadan önce, hayatın en şafağında, her zaman aldatıcı bir sadelik ve saflık ânı bahşeder."
  },
