  Stage_99725_Desc = {
    Text = "Eleştiri sanatçının görevi değildir; yaratmak öyledir."
  },
  Stage_99725_Name = {
    Text = "Balçık Üzerinde Salon"
  },
  Stage_99726_Desc = {
    Text = "Biz hep aynı terazide sıkışıp kaldık, birbirimize karşı koyduk; ama sevgili kardeşim, onu imha edemesek bile, o teraziden atlamayı seçebilirdik."
  },
  Stage_99726_Name = {
    Text = "Devrilmiş Terazi"
  },
  Stage_99727_Desc = {
    Text = "Birbirine sokulmuş bir kuş çifti; kaderleri, yalnızca bir kafeste şarkı söylemek."
  },
  Stage_99727_Name = {
    Text = "İkiz Kuşlar"
  },
  Stage_99728_Desc = {
    Text = "Hakikate tanıklık eden biri, bir düşe nasıl katlanır?"
  },
  Stage_99728_Name = {Text = "Bak, Ay!"},
  Stage_99729_Desc = {
    Text = "Kaderin saati en kötüsüdür; kaybı daima çok erken, sahip oluşu ise daima çok geç getirir."
  },
  Stage_99729_Name = {
    Text = "Düzensiz Kader"
  },
  Stage_99730_Desc = {
    Text = "Uç, uç, özgürlüğe susamış kuş.\nYumuşak rüzgâr seni kaldırdı, fırtınalar ve gök gürültüleri arasından taşıdı; o siyah kanatlar eninde sonunda kızıl şafağı yansıtacak."
  },
  Stage_99730_Name = {
    Text = "Saf Siyah Kanatlar"
  },
  Stage_99731_Desc = {
